-- The Nueva School — 2026–2027 Upper School Course Catalog import
--
-- Adds "The Nueva School" and its full 2026–2027 catalog to the existing schema:
--   schools -> departments -> terms -> courses -> course_prerequisites / course_corequisites
--
-- Mapping:
--   Term:  "Fall & Spring" -> both | "Fall Only" -> fall | "Spring Only" -> spring | "Yearlong" -> all-year
--   Grade: "9th-12th" -> {9,10,11,12}, "10th-12th" -> {10,11,12}, "11th-12th" -> {11,12}, "9th" -> {9}, ...
--   Repeatable: Yes/No -> courses.retakeable
--   graduation_requirement: NULL in source -> '' (column is NOT NULL)
--   teacher_id: NULL (no instructors listed in the catalog)
--   Prerequisites/Corequisites: best-effort links to catalog courses; non-course requirements
--     (e.g. "approval of instructor", "Math Department Approval", placement) are left in the
--     description only. Requirement rows that don't match a course title are silently skipped.
--
-- Intended to be run once against a fresh DB (no ON CONFLICT dedup). Wrapped in a transaction.

BEGIN;

----------------------------------------------------------------------
-- 1. School
----------------------------------------------------------------------
INSERT INTO schools (name, website, city, state)
VALUES ($c$The Nueva School$c$, $c$https://www.nuevaschool.org$c$, $c$San Mateo$c$, $c$CA$c$);

----------------------------------------------------------------------
-- 2. Departments
----------------------------------------------------------------------
INSERT INTO departments (school_id, name, code, graduation_requirement)
SELECT s.id, d.name, d.code, COALESCE(d.graduation_requirement, '')
FROM schools s
CROSS JOIN (
  VALUES
    ($c$Arts$c$, $c$ARTS$c$, $c$One year of arts: two semesters of any two Performing Arts electives, OR two semesters (Intro & Advanced) in the same Visual Arts medium.$c$),
    ($c$Computer Science$c$, $c$CS$c$, NULL),
    ($c$Economics$c$, $c$ECON$c$, NULL),
    ($c$Engineering, Fabrication & Design$c$, $c$EFD$c$, NULL),
    ($c$English$c$, $c$ENG$c$, $c$4 years: English 9, English 10, English 11, plus one Fall English 12 elective and one Spring English 12 elective.$c$),
    ($c$History$c$, $c$HIST$c$, $c$3 years: History 9, History 10, History 11.$c$),
    ($c$Interdisciplinary$c$, $c$INTD$c$, NULL),
    ($c$Languages$c$, $c$LANG$c$, $c$3 consecutive years of the same language.$c$),
    ($c$Math$c$, $c$MATH$c$, $c$3 years, completing at least Math 3.$c$),
    ($c$Science$c$, $c$SCI$c$, $c$Chemistry, Biology, and a 3rd year of science: either two semester-long science electives or one year-long science elective.$c$),
    ($c$SEL$c$, $c$SEL$c$, $c$4 years: SEL 9 + DCI 9, SEL 10, SEL 11, Senior Block (Fall) + SEL 12: The Good Life (Spring).$c$)
) AS d(name, code, graduation_requirement)
WHERE s.name = $c$The Nueva School$c$;

----------------------------------------------------------------------
-- 3. Terms
----------------------------------------------------------------------
INSERT INTO terms (school_id, name, season, year)
SELECT s.id, t.name, t.season, t.year
FROM schools s
CROSS JOIN (
  VALUES
    ($c$Fall 2026$c$, $c$fall$c$, 2026),
    ($c$Spring 2027$c$, $c$spring$c$, 2027),
    ($c$Fall & Spring 2026-2027$c$, $c$both$c$, 2026),
    ($c$All Year 2026-2027$c$, $c$all-year$c$, 2026)
) AS t(name, season, year)
WHERE s.name = $c$The Nueva School$c$;

----------------------------------------------------------------------
-- 4. Courses
----------------------------------------------------------------------
INSERT INTO courses (school_id, department_id, term_id, title, subject, term, grade, retakeable, short_description, long_description, teacher_id)
SELECT s.id, d.id, t.id, x.title, x.subject, x.season, x.grade, x.retakeable, x.short_description, x.long_description, NULL
FROM (
  VALUES
  -- ============================= ARTS: PERFORMING ARTS =============================
  ($c$Dance$c$, $c$Performing Arts$c$, $c$Arts$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], true,
   $c$An energetic, physically active exploration of dance across jazz, ballet, and a class-chosen style, culminating in a performance.$c$,
   $c$This course is an energetic exploration of dance. Divided into three parts over the course of the semester, students will immerse themselves in three different styles of dance: jazz, ballet and a style chosen by the class (tap, hip hop, contemporary, musical theatre, modern, or any other popular requests from students). We will explore the historical background of each style of dance, watch and learn from performances and notable performers and then learn the technique of each style. This elective is physically active and students will be encouraged to explore creativity with movement. Each class will involve a warm up, a focus on dance technique and learning choreography in each style. We will end the semester in a culmination performance of at least one of our dances. Students will receive PE credit for the full year for taking this elective.$c$),

  ($c$Fall Production$c$, $c$Performing Arts$c$, $c$Arts$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Rehearse, stage, and present a full-length play, with roles for actors, tech crew, and design teams.$c$,
   $c$Fall Production is open to all students and will offer the opportunity to rehearse, stage, and present a full-length play. Students are encouraged to contribute in ways beyond just acting, and there will be opportunities available during the rehearsal and production process for people of diverse talents and interests, including tech crew and design teams. We will begin by workshopping two different scripts and students will vote on which play we produce and perform. We will then move into academic and dramaturgical work, transitioning to the creative processes of interpretation, blocking, staging, and performance as we ready the play to be presented to the wider community. Rehearsals will be held during class time, with 2-3 after-school sessions per week, culminating in an immersive Tech Week. Any time we have left in the semester after our production will be spent doing theatrical workshops, additional acting scenes, or other opportunities to work on scripts. NOTE: All performances and technical rehearsals, which take place after school, are mandatory.$c$),

  ($c$Groove Workshop$c$, $c$Performing Arts$c$, $c$Arts$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A music performance workshop on how to form and maintain a band, covering song structure, rehearsal, and performance.$c$,
   $c$Groove Workshop is a music performance workshop designed to teach students how to form and maintain a band — in other words, how to rock! Areas covered will include analysis of song form and structure, rehearsal methods, chart writing, equipment setup, and performance tips and tricks. A big part of being in a successful band is having the ability to communicate and be open to the ideas of others. Making music is a great way to create bonds and build teamwork. This class gives students that opportunity. Goals: master the songs we choose to learn, develop proficiency as musicians through playing challenging music, learn to play well as a band, and perform both at Nueva and in the community. As this is considered an advanced group, students are expected to be proficient at all their individual parts for each song we learn. NOTE: Any and all outside school performances are mandatory. Prerequisites: None, but some musical experience is encouraged.$c$),

  ($c$Hit Harmonics: Studio Recording from Idea to Record$c$, $c$Performing Arts$c$, $c$Arts$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A studio-based course exploring how songs are built and why they resonate, through analysis, ear training, and hands-on production.$c$,
   $c$Hit Harmonics is a studio-based music course exploring how songs are built and why they resonate. Through close listening, song analysis, ear training, lyric study, and hands-on production, students examine the rhythmic, harmonic, lyrical, melodic, and structural choices that shape emotional impact. Using the full capabilities of the Upper School recording studio, students analyze influential recordings and apply those insights through original compositions, creative reinterpretations, and the collaborative production of a class-built track. Throughout the semester, students contribute to a shared class sound library, developing a curated collection of grooves, harmonies, textures, and recorded material that becomes a living resource for composition. By semester's end, students will have produced finished works, including a collaborative class song, and developed a deeper understanding of how musical decisions shape the listener's experience.$c$),

  ($c$Intro to Music Production$c$, $c$Performing Arts$c$, $c$Arts$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Learn the fundamentals of music production using Ableton Live, from MIDI programming to recording and sound design.$c$,
   $c$Students will learn how to create any type of music that they can dream of, using imagination and the program Ableton Live. Students will learn the fundamental concepts of music production, covering everything from programming electronic compositions using MIDI to recording live instruments and vocals to designing, engineering, and automating their own sounds. Students use musical examples from the industry to understand certain concepts in digital production and learn how to design and produce music using their own sounds and patches. Course assignments include creating musical compositions or designing sounds and patches for future productions using Ableton and are flexible in regard to genre and style (electronic vs. live). The course will model a workshop environment, as we will listen to and discuss student projects as a group. At the end of the course, students produce a final original song at full length.$c$),

  ($c$Jazz Ensemble$c$, $c$Performing Arts$c$, $c$Arts$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Study and perform jazz styles including blues, swing, Latin, and Brazilian, with an emphasis on improvisation. Students must play an instrument.$c$,
   $c$Jazz Ensemble will study and perform various jazz stylings, including blues, swing, Latin, Brazilian, and calypso. Each style will be explored historically, theoretically, and in performance. Emphasis will be on the basic concepts of each style as well as improvisation. Students will be exposed to "standards," the classic compositions that are an integral part of any jazz musician's vocabulary. In addition to performing at the upper school arts culmination in December, we will look for other opportunities to perform at open houses and informal lunch concerts and morning meetings. Grading will be based on attendance and participation in class. The Jazz Ensemble is designed to increase a student's musical proficiency, rhythmic vocabulary, ability to improvise, knowledge of theory, and understanding of that uniquely American art form — jazz. NOTE: Any and all outside school performances are mandatory. Prerequisite: Student must play an instrument.$c$),

  ($c$Musical Theater$c$, $c$Performing Arts$c$, $c$Arts$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Core rehearsal for the spring musical, exploring acting, voice, movement, and characterization, with tech-team options.$c$,
   $c$This elective is open to anyone interested in performing in the spring musical; it is also open to students with a strong interest in the production end of things (e.g., stage managing, tech, etc.). We will begin by workshopping two different scripts and students will vote on which musical we end up producing and performing. While the class serves as core rehearsal time, it also explores key components of acting, including voice work (breathing, articulation, projection, vocal blending, and musicality), stage movement (choreography, blocking, stage picture, and physicality of character) and characterization (focus and concentration, improvisation, open scene work, subtext, motivation, emotional range). Each student also has the opportunity to be a part of a tech team (costumes, props, assistant directing, sound, set design, etc) to help our show come to life. Note: students in this elective will receive 2 units of P.E. credit. NOTE: There will be two after school rehearsals per week for the first part of the semester, moving to three closer to the show, culminating in an immersive tech week and a performance weekend. All performances and technical rehearsals are mandatory.$c$),

  ($c$Sound Experience$c$, $c$Performing Arts$c$, $c$Arts$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Explore how sound works, from the physics of vibration to digital audio production, field recording, and sound design.$c$,
   $c$In this course, students will explore how sound works—from the physics of vibration and waveforms to the emotional impact of music and auditory storytelling. We will cover a wide range of topics, including psychoacoustics, digital audio production, field recording, and sound design. One primary focus will be studying and creating sounds for video—from sound effects (Foley) to film scores. Students will gain hands-on experience working with a Digital Audio Workstation (DAW), microphones, and recording gear as they learn how to shape sound for different artistic and communicative purposes. The course will culminate in a final project where students create an original audio experience or research-based presentation. Students who play instruments will be encouraged to incorporate their musical abilities into their work.$c$),

  ($c$Steel Drum Band$c$, $c$Performing Arts$c$, $c$Arts$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Develop an advanced steel drum ensemble playing complex arrangements across a variety of musical styles.$c$,
   $c$The steel band will explore a variety of music styles, potentially learning compositions by Trinidadian steel drum virtuoso Robert Greenidge. In addition to learning the calypso stylings of Robert's music, we will most likely do several Santana tunes as well as music by Sting and Bill Withers. While the exact composers and compositions may vary by semester, the rhythms of each style present different challenges for each section of the band. The goal of the class is to develop an advanced steel drum ensemble for the high school that will play complex arrangements in a variety of musical styles. The ensemble will perform at school and in the community throughout the year, including the upper school arts culmination in early December. Students will also research the history of the instrument, its cultural significance, its pioneers, and its greatest composers and performers. NOTE: Any and all outside school performances are mandatory.$c$),

  -- ============================= ARTS: VISUAL ARTS =============================
  ($c$Intro to Art & Fabrication$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A semester course combining visual art and fabrication, using hand tools, power tools, and varied materials.$c$,
   $c$This semester-long course combines the fields of visual art and fabrication. Students in this course work in a variety of media to create projects that demonstrate understanding and consideration of craftsmanship and the elements and principles of visual art, including space, form, balance, light, and contrast. Students gain firsthand knowledge and experience with construction by using a variety of hand tools, power tools, and materials, such as the hand drill, chop saw, band saw, belt and orbital sanders, wire, foam, wood, and sheet metal. Emphasis is placed on appropriate use of tools and safety. Students create work that can range from representational to abstract; it might be inspired by historical or contemporary artists and art movements. Through readings, slide presentations, and visiting artists, students consider the context in which they are creating art. Students participate in critiques as a means to develop critical thinking skills and to further understand the meaning in their work.$c$),

  ($c$Intro to Clay Sculpture$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A studio class exploring three-dimensional thinking with clay as the primary medium, for beginners and experienced students alike.$c$,
   $c$Intro to Sculpture is a studio class that explores ways of thinking three-dimensionally, with clay as the primary medium. It serves the needs of beginners and experienced students of art. In addition to sculpture techniques, the elements of the three-dimensional art and design will be studied as they apply to the projects at hand. Students work in both subtractive and additive manners, incorporating basic aesthetic concepts such as line, texture, composition, balance, mass, space, rhythm, tension, movement, light, and density. Students explore the relationship between form and content in materials through hand-building techniques in clay. Projects investigate representation (people and things), abstraction, and architecturally inspired design/installation. Students are encouraged to think about the conceptual possibilities of sculpture and expressing a personal point of view. Students participate in a culminating upper school gallery showing, presentations, and critiques.$c$),

  ($c$Intro to Drawing$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A studio course focused on technical drawing skill and mark-making across a variety of media.$c$,
   $c$Drawing considers our perception, observation, and knowing of the world around us. It is a method of recording and expression in a visual language all its own. This studio course focuses on technical skill as well as mark-making as a form of creative exploration. Students will examine their interests and ideas through visual representation, working both technically and intuitively. Though class time will include lessons and discussions, students will typically be working on projects using a variety of drawing media, including (but not limited to) graphite, charcoal, and colored pencil. Studio time encourages a quiet focus and provides the necessary hours to build and refine the connection between the hand and eye. We will explore historically significant and contemporary artists, along with concepts in visual and critical studies. Students are strongly encouraged to participate in a culminating art show at the end of the semester.$c$),

  ($c$Intro to Film & Video$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Investigate the moving image as artistic and conceptual exploration through experimental techniques and short projects.$c$,
   $c$This course introduces students to the moving image as a form of artistic and conceptual exploration. Rather than focusing on traditional narrative storytelling, students will investigate how meaning is created through time, rhythm, framing, and editing. Working with digital cameras and editing software, students will learn the technical foundations of video production alongside experimental approaches to image-making. Through a series of short projects, students will explore techniques such as looping, sequencing, duration, and montage, while engaging with both contemporary and historical examples of film and video art. Students will be introduced to artists who use video as a primary medium, considering how moving images can function beyond conventional cinema. Emphasis is placed on creative risk-taking, visual literacy, and the development of an intentional relationship to the camera and editing process.$c$),

  ($c$Mixed Media$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A studio course exploring 2D processes including drawing, painting, collage, and digital media.$c$,
   $c$Mixed Media is a studio course that explores a range of 2D processes including (but not limited to) drawing, painting, collage, and digital media. Throughout the semester, students will utilize different surfaces and materials in both traditional and alternative methods. Working with representation and abstraction, students will be encouraged to experiment within the framework and assignments of the class. Course content will address our daily visual experiences, whether through the screens on our devices or actual objects. More specifically, we will examine texture and dimension as illusion on a flat surface through the act of art making. We will consider these modes of seeing through juxtaposing and combining digital and other 2D media. This class seeks to develop the student's sense of visual literacy and personal art practice, building technical skill and fostering independent and creative thought. Students are strongly encouraged to participate in a culminating art show at the end of the semester.$c$),

  ($c$Intro to Painting$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A studio class working with gouache and acrylic to explore color, light, space, and the handling of paint.$c$,
   $c$Intro to Painting is a studio class that teaches students about working with paint and exploring a range of applications. The course covers color, light, space, and the handling of paint (gouache and acrylic) in addition to exploring the beauty of forms and color. Students will be painting people, places, and things while simultaneously exploring ideas about abstraction, representation, and expression. Students are encouraged to reflect on their own lives, experiences, interests, and hobbies as inspiration for their work while building their painting skills. Aside from studio work, there will be critiques, sketchbook homework, some reading, and writing. The ultimate goal is for each student to develop an individual visual vocabulary and to transform an assignment into a quest that demonstrates curiosity, commitment, and craft.$c$),

  ($c$Intro to Photography$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A digital studio class on making images and the fundamentals of art and design as they pertain to photography.$c$,
   $c$This studio class will focus on making images and the fundamentals of art and design as they pertain to photography. As a digital class we will work with DSLRs to complete six bodies of work. Students will spend a lot of time making the images and honing skills around composition. In addition to photographic composition, students will learn other technical skills such as camera Raw, Photoshop and digital printing. In addition to making the images, we will build skills around visual literacy, and work on communicating through the images we make. Through readings, slide presentations, and visiting artists, students will consider the context in which they are creating photographs. Students will participate in critiques to develop critical thinking skills and gain a deeper understanding of their work. At the end of the term, students will participate in a school wide art exhibition. This beginning class will be a prerequisite to the Advanced Photography class using the darkroom.$c$),

  ($c$Adv. Art & Fabrication$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Builds on Intro to Art & Fabrication, deepening shop skills and artistic practice to create robust 3D art.$c$,
   $c$Advanced Art and Fabrication will build on skills introduced in the first semester of Art and Fabrication. Students in this course work in a variety of media to create projects that demonstrate understanding and consideration of craftsmanship and the elements and principles of visual art, including space, form, balance, texture, and contrast. Students gain firsthand knowledge and experience with construction by using a variety of hand tools, power tools, and materials, such as the hand drill, chop saw, band saw, belt and orbital sanders, wire, foam, wood, and sheet metal. Emphasis is placed on appropriate use of tools and safety. The course aims to empower artists with fundamental shop skills to create physical objects, and to introduce more mechanically-inclined students to artistic and creative processes. All students, regardless of former capabilities, will grow their knowledge of and skills in both art and fabrication by applying each in the context of the other. Students are strongly encouraged to participate in a culminating art show at the end of the semester.$c$),

  ($c$Adv. Clay Sculpture$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Builds on Intro to Clay Sculpture, continuing to explore three-dimensional thinking with a range of clay bodies.$c$,
   $c$Advanced Sculpture is a studio class that builds on the foundations of the Introduction to Sculpture class. Students continue to explore making sculpture with a range of clay bodies as the primary medium and ways of thinking three-dimensionally. This class serves the needs of beginners and experienced students for art. In addition to sculpture techniques, the elements of the three-dimensional art and design will be studied as they apply to the projects at hand. Students work in both subtractive and additive manners, incorporating basic aesthetic concepts such as line, texture, composition, balance, form, mass, space, rhythm, tension, movement, light, and density. Students explore the relationship between form and content in materials through hand building techniques in clay. Projects investigate representation (people and things), abstraction, and architecturally inspired design/installation. Students are encouraged to think about the conceptual possibilities of sculpture and expressing a personal point of view.$c$),

  ($c$Adv. Drawing$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Builds on Intro to Drawing with advanced techniques such as one-, two-, and three-point perspective.$c$,
   $c$Advanced Drawing builds on drawing skills introduced in the first semester of Drawing. This studio course focuses on technical skill as well as mark-making as a form of creative exploration. Students will examine their interests and ideas through visual representation, working both technically and intuitively. Though class time will include lessons and discussions, students will typically be working on projects using a variety of drawing media, including (but not limited to) graphite, charcoal, and colored pencil. Studio time encourages a quiet focus and provides the necessary hours to build and refine the connection between the hand and eye. We will explore historically significant and contemporary artists, along with concepts in visual and critical studies. We will learn techniques such as, but not limited to, one, two, and three-point perspective, as well as experimenting with the alternative stylus.$c$),

  ($c$Adv. Film & Video$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Builds on Intro to Film & Video, developing an individual artistic voice through sustained time-based projects.$c$,
   $c$This course builds on foundational skills in moving image-making and focuses on the development of an individual artistic voice. Students will work with digital video and editing software to create sustained projects that explore personal, social, or conceptual ideas through time-based media. Expanding on approaches introduced in the introductory course, students will deepen their understanding of duration, sequencing, and structure, while exploring a range of strategies including observational, constructed, and hybrid forms. Emphasis is placed on intentionality, experimentation, and the refinement of ideas through iterative making. Students will engage with contemporary artists working in film and video, situating their work within broader artistic and cultural contexts. Through critique, reflection, and revision, students will develop a cohesive body of work that demonstrates a more advanced ability to shape meaning through image, sound, and time.$c$),

  ($c$Adv. Painting$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Builds on Intro to Painting, continuing work with acrylic and oil across color, light, space, and paint handling.$c$,
   $c$Advanced Painting is a studio class that builds on the Introduction to Painting curriculum and is a continuation in working with paint and exploring a range of applications. The course covers color, light, space and the handling of paint (acrylic and oil) in addition to exploring the beauty of forms and color. Projects in class range from painting people, places and things while simultaneously exploring ideas about abstraction, representation and expression. Students are encouraged to reflect on their own lives, experiences, interests and hobbies as inspiration for their work while building their painting skills. Aside from studio work, there will be critiques, sketchbook homework, some reading, and writing.$c$),

  ($c$Adv. Photography$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A second-level studio class exploring creative photographic techniques with a focus on making images.$c$,
   $c$In this second level studio class, we will explore creative techniques in photography with a focus on the act of making images. In most of our classes we will be talking together as a class rather than having the instructor talk at the students. Students will complete several collections of photos or photo essays. In this class, we will examine the decisions involved in taking a picture. You will learn the technical skills (camera, RAW/Lightroom/Photoshop, digital printing) needed to produce "good" photographs. Short readings, slide shows, artist documentaries and class discussions will add theoretical grounding to a series of independent shooting assignments. We will critique assignments as a group and develop a practice of constructive peer review.$c$),

  ($c$Adv. Studio Art$c$, $c$Visual Arts$c$, $c$Arts$c$, $c$all-year$c$, $c${11,12}$c$::int[], true,
   $c$A yearlong upper-division studio class for students building a cohesive art portfolio across mediums. Prereq: any two full visual art courses (Intro & Advanced).$c$,
   $c$Advanced Studio Art is a class for students who want to continue making art and are interested in building a portfolio. Students in this upper division class will have taken an art class before and will drive their own exploration and art making. Students will have the opportunity to work in a community of other students who are committed to making and discussing art. Over the course of the semester, students will choose artistic research interests and make work based on those interests. This studio class will be focused on critique of student work in addition to making work; discussions and readings will provide a frame for the critiques. An emphasis will also be placed on larger portfolio goals, and students will work toward achieving a cohesive portfolio with depth in addition to breadth. Students will work across mediums, according to their interest and portfolio needs. Advanced Studio Art students will be expected to participate in the arts culmination at the end of the semester. Prerequisites: Any 2 full visual art courses (Intro & Advanced).$c$),

  ($c$Fine Arts Teaching Fellowship$c$, $c$Arts$c$, $c$Arts$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired arts course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$),

  -- ============================= COMPUTER SCIENCE =============================
  ($c$Advanced Machine Learning$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$spring$c$, $c${10,11,12}$c$::int[], false,
   $c$Builds on Intro Machine Learning to explore neural networks for regression, classification, and image identification. Prereq: at least one non-intro CS elective.$c$,
   $c$You might enjoy this course if you enjoyed Intro Machine Learning, you are curious about how neural networks work, or you want to see math concepts applied outside of math classes. Helpful prior experience includes Intro Machine Learning, comfort thinking conceptually about math, working with data in numpy and pandas, and comfort reading and writing code in at least one programming language. During this class, we will cover dense neural networks for regression and classification, convolutional networks for image identification, and training and tuning neural networks. Prerequisites: At least one non-intro computer science elective at Nueva Upper School.$c$),

  ($c$Algorithms$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$An introduction to theoretical computer science: proofs, asymptotic analysis, data structures, and algorithm design.$c$,
   $c$You might enjoy this class if you think you might want to study computer science in college, you want to know whether "computer science" and "programming" are the same thing (they're not), you are interested in areas of computer science that do not involve programming, or you like puzzles, math, and the feeling of things making sense. Helpful prior experience includes foundational programming skills; concepts from Math 2 (limits and logarithms) are helpful but not required. Topics include proofs (ensuring code is correct and terminates), asymptotic analysis, PageRank and SEO, data structures beyond arrays/lists/objects, stable matching, techniques for designing and analyzing algorithms (finite state machines, dynamic programming, relaxation), and advanced topics in theoretical computer science. Prerequisites: Completion of Intro to Computer Programming or Intro to Data Analysis, or approval of instructor.$c$),

  ($c$Computer Security$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Explore threats against online systems and how to protect against them, from cryptography to authentication and forensics.$c$,
   $c$You might enjoy this class if you are curious about the various types of threats against online systems and how to protect against them, and you enjoy having freedom to choose your own projects and topics of exploration responsibly. No prior experience with computer security is required; foundational programming skills will be needed to complete some assignments. Topics include the legality and ethics of computer security and hacking, defending against injection attacks with user input validation, cryptography, authentication, authorization, and forensics. Prerequisites: Completion of Intro to Computer Programming or Intro to Data Analysis, or approval of instructor.$c$),

  ($c$Computer Vision$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Explore how computers extract meaning from images and video, and discuss the ethics of computer vision applications.$c$,
   $c$You might enjoy this class if you want to explore the many ways that computers extract meaning from images and video, you are interested in investigating the ethics of computer vision applications (government surveillance, automated weapons, self-driving cars), and you enjoy choosing your own projects responsibly. Foundational programming skills are required. Topics include image representation and encoding, filters (both effects and information-extracting operations), detecting edges, features, and objects, a framework for thinking about who might be affected by computer vision technology, and advanced topics such as facial recognition, automatic image resizing, object tracking, scene graphs, and image segmentation. Note: this course will likely not run again until 2028. Prerequisites: Completion of Intro to Computer Programming or Intro to Data Analysis, or approval of instructor.$c$),

  ($c$Data Science$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Learn to gather, clean, analyze, and visualize data to gain insights and communicate findings.$c$,
   $c$You might enjoy this class if you are not a "CS person" but think it is important to know how to work with data, you are curious about how data can be used to gain insights and influence policy, you like infographics and novel ways of presenting information, or you want more practice programming. Foundational programming skills are needed for some assignments. Topics include ways to get data, cleaning up data, using statistical tools to gain insights, recognizing and avoiding bias in surveys, using R, Ruby, and Tableau, creating novel and aesthetically pleasing data visualizations, and how to answer questions and communicate findings using data. Prerequisites: Completion of Intro to Computer Programming or Intro to Data Analysis, or approval of instructor.$c$),

  ($c$Intro to Computer Programming$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A starting point on the CS pathway: learn to write basic Python, structure data, and think like a programmer.$c$,
   $c$You might enjoy this course if you want to learn how to program, you want to dive deep into programming and how to do it well, or you are looking for a place to get started on your CS pathway. Open to all curious folks; any form of problem solving is helpful prior experience. During this class, we will cover how to write basic Python (variables, loops, functions, etc.), how to organize and structure data, how to create games and other interactive visuals, how to think like a programmer, and how to begin planning a project and make it on your own.$c$),

  ($c$Intro to Data Analysis$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Learn basic Python to collect, organize, analyze, and visualize data.$c$,
   $c$You might enjoy this course if you want to learn how to program, you think data is neat, you want to use data to analyze words, numbers and other things, or you want to learn Python to make graphs. Open to all curious folks; any form of problem solving is helpful prior experience. During this class, we will cover how to write basic Python (variables, loops, functions, etc.), how to organize collected data (numbers and words), how to analyze and manipulate data, how to create graphs and other visuals for data, how to structure large amounts of data, how to use Python and Colab to write up a lab or analysis report, and how to begin planning a project on your own.$c$),

  ($c$Intro to Machine Learning$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$fall$c$, $c${10,11,12}$c$::int[], false,
   $c$Learn how machine learning works through classical models and the ethics of model-building. Prereq: at least one non-intro CS elective.$c$,
   $c$You might enjoy this course if you want to know how machine learning works, you like working with data, or you want to see math concepts applied outside of math classes. Helpful prior experience includes comfort thinking conceptually about math and comfort reading and writing code in at least one programming language. During this class, we will cover classical models such as linear regression, classification, and clustering; organizing and preparing data for a model; validating models to make sure they work well; and ethical considerations of models and the decisions we make in creating them. Prerequisites: At least one non-intro computer science elective at Nueva Upper School.$c$),

  ($c$Mobile App Development$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Learn to build mobile apps with React Native, using device hardware and engaging with app-development ethics.$c$,
   $c$You might enjoy this course if you are curious about the inner workings of mobile apps, you are curious about how phone apps keep people engaged, or you want to make your own cool app. Foundational programming skills are needed to complete assignments. During this class, we will cover how to write code that works for mobile devices, how to pull data from hardware such as location, Bluetooth, rotation, GPS, and cameras, how to organize and structure code for React Native, how to plan and test designed applications on mobile devices, and how to engage with ethics related to app development. Prerequisites: Completion of Intro to Computer Programming or Intro to Data Analysis, or approval of instructor.$c$),

  ($c$Programming with OOP$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Learn object-oriented programming: classes, objects, inheritance, and structuring larger programs.$c$,
   $c$You might enjoy this course if you want to make games or model interactions, you want to be a more efficient programmer, you want to learn how to structure larger and more complex programs, you want to learn more about classes and objects, or you want to understand the organization of the libraries you use. Foundational programming skills are needed to complete assignments. During this class, we will cover classes and objects, inheritance and the organization of connected classes, common strategies for writing well-organized classes, and how to think through and plan out larger projects. Prerequisites: Completion of Intro to Computer Programming or Intro to Data Analysis, or approval of instructor.$c$),

  ($c$Software Engineering$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$fall$c$, $c${10,11,12}$c$::int[], true,
   $c$A taste of real-world software development: prototyping, iteration, testing, documentation, and code reviews. Prereq: at least one non-intro CS elective.$c$,
   $c$You might enjoy this class if you have ever wondered what the difference is between programming for homework and real-world software development, you want a taste of what it is like to work in the software industry, you like using your programming ability to help people, or you enjoy choosing your own projects responsibly. Having developed an app (web, mobile, or otherwise) can be helpful but is not necessary. Topics include how to build software that people actually want, software prototyping and iteration, task estimation and prioritization, building a minimum viable product, documentation and specification, testing and development paradigms, defensive programming, and code reviews. Prerequisites: At least one non-intro computer science elective at Nueva Upper School and comfort reading and writing code in at least one programming language.$c$),

  ($c$Video Game Programming$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Make video games using the Godot game engine, covering controls, levels, enemies, items, and physics.$c$,
   $c$You might enjoy this course if you want to understand the process of making video games better, you like being creative and coming up with new ideas, or you like making things for other people to play with. Playing or enjoying games of any type and foundational programming skills are helpful prior experiences. During this class, we will cover the basics of the Godot game engine, controls and interaction with your game, using tilemaps to create levels, creating enemies and items, and adding physics to games. Prerequisites: Completion of Intro to Computer Programming or Intro to Data Analysis, or approval of instructor.$c$),

  ($c$Computer Science Teaching Fellowship$c$, $c$Computer Science$c$, $c$Computer Science$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired CS course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$),

  -- ============================= ECONOMICS =============================
  ($c$Business Analytics$c$, $c$Economics$c$, $c$Economics$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Explore the quantitative tools of management science across optimization, dynamics, and uncertainty, ending in a business plan competition.$c$,
   $c$This elective explores the quantitative tools of management science in different business models. The course is structured around four modules. The first three modules investigate three distinct analytic methodologies, while the final one pits students, in small groups, in a business plan competition. The first module explores "Models of Optimization," using the framework of mathematical programming; we learn to use linear inequalities to represent decision problems and exploit convexity to approximate optimal solutions. The second module examines "Models of Dynamics," using causal loop diagrams to track stocks and flows and computational tools for assessing growth behavior and path dependence. The third module introduces "Models of Uncertainty," using queueing systems and their networks; we learn about Markov Chains and design Monte Carlo simulations to propagate risk through a network of business decisions.$c$),

  ($c$Economic Inequality$c$, $c$Economics$c$, $c$Economics$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Use macroeconomic models and statistical tools to understand and forecast the effects of economic inequality around the globe.$c$,
   $c$Economic Inequality is the driving force behind many of the most significant political upheavals of the 21st century. This one-semester course leverages macroeconomic models and statistical tools to understand and forecast the effects of economic inequality around the globe. Students begin by teaching each other about the mechanics and importance of major indexes to measure economic inequality, then read and critique Piketty's Capital in the 21st Century. The class dives into texts, pilot programs, and proposals concerning universal basic income, culminating in academic debates. The analysis examines the economic underpinnings of racial inequality in America through mass incarceration and federal housing policy, and students conclude by interviewing stakeholders about affordable housing development. There are no required prerequisites; students who have taken macroeconomics will find this a relevant application of those tools.$c$),

  ($c$Economic Thesis Seminar$c$, $c$Economics$c$, $c$Economics$c$, $c$spring$c$, $c${11,12}$c$::int[], true,
   $c$A research team making innovations in exciting areas of economic research. Prereq: any economics class and History 10.$c$,
   $c$Economic Thesis Seminar comprises a team of researchers that spends each spring semester making innovations in the most exciting areas of economic research. In prior classes, students have worked with a United Nations commission to investigate blockchain for environmental market failures, designed a new insurance model to reduce the influence of Super PACs, modelled the economic effects of LibGen on academic publishing, and forecasted the effects of a legalized sex work market in California, among many other projects. Most projects utilize mathematical modeling and data analysis, but there is also a need for researchers focused on writing and reading research. Expected workload significantly exceeds the average asked of students in other classes. This course is exclusively open to 11th and 12th graders who have taken at least one prior high school economics class. Prerequisites: Any economics class and History 10.$c$),

  ($c$Environmental Economics$c$, $c$Economics$c$, $c$Economics$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A focused study of environmental economics through academic papers, microeconomic models, and the Electricity Strategy Game.$c$,
   $c$Environmental economics is possibly the most consequential field of the entire discipline, while simultaneously being the subject which traditional economics fails most comprehensively to understand. This focused semester-long course attempts to answer some of the most complex questions facing economists today: How should we quantitatively value the lives of future generations? How do we know the true worth of an environmental good never traded on a market? Can we design an international climate change agreement that does not implode with greed? Which forms of environmental regulation most effectively align corporate and social interests? Students work through analyzing academic papers, mathematically assessing environmental policies through algebra- and calculus-based microeconomic models, and creating independent research projects. Our class is the only high school in the nation chosen to participate in the Electricity Strategy Game. Note: Intro to Microeconomics is a helpful but not required prerequisite.$c$),

  ($c$Intro to Macroeconomics$c$, $c$Economics$c$, $c$Economics$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Introduces the tools and models to understand economic crises through growth, inflation, employment, and trade.$c$,
   $c$Macroeconomics is the study of the most pressing issues facing global economies today. This course introduces students to the tools and models necessary to understand current and historical events. Students analyze the causes and effects of economic crises through considerations of growth, inflation, employment, income, productivity, and trade. They gain insight into fiscal and monetary policy by grappling with questions such as: What policies and economic conditions led to the Great Depression and the Great Recession? Could the New Deal have rescued the United States economy if World War II had never occurred? Why was the Federal Reserve desperate to increase inflation after 2008? Who are the winners and losers of modern free trade agreements? Is it possible to achieve economic equality while maximizing economic growth?$c$),

  ($c$Intro to Microeconomics$c$, $c$Economics$c$, $c$Economics$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Introduces the core questions, models, and tenets of microeconomics through texts, case studies, and simulations.$c$,
   $c$This course introduces students to the core questions, models, and tenets of microeconomics. Together, we analyze the economic rationale and consequences of choices made by consumers, businesses, and government within our broader economic system. Through academic texts, news articles, case studies, and in-class games and simulations, we expand our understanding of why economic decisions are made and how to predict and evaluate their consequences. We turn a critical eye to the neoclassical economic view while learning its inner workings. Goals include understanding consumer behavior, non-cooperative game theory, and the limits of economic rationality; predicting firm behavior in terms of price, quantity, market entry, and efficiency; analyzing market structures including competitive markets, monopolies, and oligopolies; exploring market failures; and understanding the effects of government policies on market outcomes.$c$),

  ($c$Models of Group Decisions$c$, $c$Economics$c$, $c$Economics$c$, $c$spring$c$, $c${10,11,12}$c$::int[], false,
   $c$Explore political economy and modeling paradigms—game theory, auctions, voting—that shape collective decisions. Prereq: Intro to Microeconomics and Math 2.$c$,
   $c$In this elective we read widely to familiarize ourselves with elements of political economy and the role of institutional arrangements for aggregating preferences in a historical and global context. We explore modeling paradigms, from game theory and auctions to voting schemes, in an attempt to disentangle the non-market forces that shape the economy. Limits to rationality and a host of behavioral norms and biases challenge us to develop rich enough models to accommodate them. This course probes the interface between social science and mathematics, both in substance and in modes of inquiry, involving readings and debate as well as computer modeling of interacting economic agents. Prerequisites: Intro to Microeconomics and Math 2.$c$),

  ($c$Economics Teaching Fellowship$c$, $c$Economics$c$, $c$Economics$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired economics course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$),

  -- ============================= ENGINEERING, FABRICATION & DESIGN =============================
  ($c$All About Wearables$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Design and construct wearable pieces, from decoding sewing patterns to adding simple electronics with Microbits and Lilypad Arduinos.$c$,
   $c$You might enjoy this class if you have ever wanted to customize your clothes, you are curious about electronics but love soft materials, you enjoy sewing, knitting, crocheting, or embroidery, you are curious about how clothing is constructed, you like turning a flat piece of fabric into a 3D object, or you want to experiment with adding simple electronics to wearable designs. A little hand sewing or circuit experience is helpful but not required. During this class, we will learn what different fabrics and materials are made of and why it matters, decode sewing patterns and transform them into wearable pieces, master stitches that hold projects together, and explore Microbits and Lilypad Arduinos and how they bring electronics into fashion.$c$),

  ($c$Applied Engineering: Biomedical$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$fall$c$, $c${10,11,12}$c$::int[], false,
   $c$Tackle complex engineering design problems like wearable sensors and surgical robots through open-ended projects. Prereq: Physics.$c$,
   $c$You might enjoy this class if you are interested in more complex engineering design problems, like wearable sensors or surgical robots, you want the freedom to work on open-ended design and fabrication projects, or you are curious about the difference between engineering homework and real-world engineering. Helpful prior experience includes comfort working in the I-Lab, basic electronics and coding with microbit or arduino, and basic CAD and 3D modeling. Topics include engineering project planning, engineering testing and design, intermediate design and fabrication, and intermediate controls and microcontroller programming. Prerequisites: Physics.$c$),

  ($c$Architecture of Unbreakable Homes$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Explore future-proof, disaster-resistant housing through engineering techniques, materials, and models.$c$,
   $c$You might enjoy this class if you are interested in future-proof housing, you are fascinated by architecture, engineering, or how things are built, you care about climate change and adapting to increased risks, you want to know how a house goes from empty plot to finished structure, or you like problem-solving multiple challenges at once. Experience with floorplans or small models is helpful. During this class, we will explore which parts of the U.S. are at highest risk for natural disasters, analyze common building designs and why some fail, learn key engineering techniques that make structures more disaster-resistant, learn the pros and cons of different materials, and create models to communicate ideas and iterate based on feedback.$c$),

  ($c$The Art of Repair$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Learn hands-on repair and restoration skills for ceramics, fabric, and wood, including Kintsugi, while exploring sustainability and Right to Repair.$c$,
   $c$You might enjoy this class if you want to embrace imperfections like the Japanese art of Kintsugi, you are hooked on videos of craftspeople restoring things, you love making things, you are fascinated by how things are built and why they break, you care about sustainability and modern manufacturing, or you admire antiques and restorations. Familiarity with different materials is helpful. During this class, we will discover how everyday objects were made in the past vs. today, learn hands-on repair skills for ceramics, fabric, and wood, explore Kintsugi and other restoration techniques that turn damage into art, experiment with sanding, carving, and cutting wood, and explore the Right to Repair movement and why it matters.$c$),

  ($c$Building Toys$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Build toys out of a variety of materials while studying child development and what makes toys fun, engaging, and safe.$c$,
   $c$You might enjoy this class if you enjoy visiting the lower school, you want to build fun things out of a variety of materials, you are curious about the secrets behind your favorite childhood toys, you think little kids are fascinating, you enjoy making things with your hands, or you notice the tiny details in everyday objects. Having played with toys, done some fabrication, or spent time with young kids are helpful prior experiences. During this class, we will explore how kids of different ages develop as they play, discover toys of the past and what made them fun, engaging, and safe, and put toys to the test to see whether you can make something that kids fall in love with.$c$),

  ($c$Creature Comforts$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$spring$c$, $c${10,11,12}$c$::int[], true,
   $c$Use design thinking and the I-Lab to design for animal users, learning CNC routing and basic 3D modeling.$c$,
   $c$You might enjoy this class if you like cute animals and want to make them happy, you are interested in the I-Lab and learning more about design thinking, or you want to push yourself to design for a new type of user. No experience is required beyond a basic understanding of the design thinking process. During this class, we will cover how to go through the design process without the ability to interview the user, design thinking, prototyping, and iteration, how to use the CNC router and design for it, and basic 3D modeling (CAD) skills and flatpack design.$c$),

  ($c$Design Create Innovate (DCI)$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$all-year$c$, $c${9}$c$::int[], false,
   $c$A required 9th-grade course integrating design thinking, computer science, and engineering, meeting once per week alternating with SEL 9.$c$,
   $c$Design Create Innovate integrates design thinking, computer science, and engineering into a single course that all 9th graders take. This course is designed to build students' creative courage and technical skills, introducing design processes, fabrication techniques, and the importance of documentation. Students master the art of navigating ambiguity as they collaborate to prototype solutions for complex challenges, requiring a commitment to continual iteration and fearless failure. By blending user-centered research—such as empathy interviewing and storyboarding—with computer science methods and systems-level evaluation, the curriculum empowers students to design impactful, technically sound solutions rooted in the needs of others. Note: DCI 9 classes meet only once per week, alternating with SEL 9 in the same block.$c$),

  ($c$Film and Stage Costume Making$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Learn how costumes are designed and made for film, TV, cosplay, and stage, including sewing and working with new materials.$c$,
   $c$You might enjoy this class if you are interested in how costumes are designed or made for movies, TV, cosplay, or stage productions, you are interested in learning to sew, or you are interested in working with new costuming and cosplay materials. No prior experience is required. During this class, we will cover costume design, costume layout and fabrication, and working with fabrics, foams, plastics, and other wearable materials.$c$),

  ($c$Film & Stage Prop Making$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Learn how props are designed, built, painted, and finished for film, TV, cosplay, and stage.$c$,
   $c$You might enjoy this class if you are interested in how props are designed or made for movies, TV, cosplay, or stage productions, you are interested in learning to build and paint props, or you are interested in working with new prop-making and cosplay materials. No prior experience is required. During this class, we will cover prop design, prop layout and fabrication, painting, finishing, and weathering props, and working with fabrics, foams, plastics, and other wearable materials.$c$),

  ($c$How to Build Anything?$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Build more complex and precise objects, learning tolerances, jigs and fixtures, and designing parts that fit and move.$c$,
   $c$You might enjoy this class if you are interested in building things that are more complex or precise, you want to progress as a builder for engineering, art, or general fabrication, or you are interested in how to make multiple items that fit together. Any I-Lab fabrication or building class is helpful prior experience. During this class, we will cover precision measurement, design and fabrication tolerances, designing for assembly and fabrication, designing and building jigs and fixtures, and designing and building things that fit together and move.$c$),

  ($c$Intro Fabrication: Metal$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Learn MIG welding, metal forming, layout, and measurement in an introductory metal fabrication class.$c$,
   $c$You might enjoy this class if you want to make sparks and learn some new tools, you are interested in welding and metal forming, or you want to learn new problem solving, measuring, and layout skills. No experience is required, though some welding experience is helpful. During this class, we will cover MIG welding steel and preparing your metal, layout tools and methods for measuring, and metal forming using breaks, benders, and heat.$c$),

  ($c$Intro to Fabrication: Wood$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Learn woodworking, wood finishing, marquetry, and measurement in an introductory wood fabrication class.$c$,
   $c$You might enjoy this class if you want to make sawdust and learn some new tools, you are interested in woodworking and wood finishing, or you want to learn new problem solving, measuring, and layout skills. No prior experience is required. During this class, we will cover complex inlaid designs using marquetry, layout tools and methods for measuring, and woodworking using saws, routers, and sanders.$c$),

  ($c$Intro to CAD$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Start designing in 3D space using CAD, from 2D sketching to modeling and building movable assemblies.$c$,
   $c$You might enjoy this class if you want to take full advantage of the I-Lab and tools like the 3D printers and laser cutters, you enjoy puzzles and figuring out efficient ways of building objects, or you want to start designing in 3D space. No prior experience is required. During this class, we will cover 2D sketching using dimensions, constraints, and parameters, modeling 3D shapes using basic and advanced tools, construction of assemblies using joints and in-model-building methods, and movable assemblies using joints and motion links.$c$),

  ($c$Intro to Mechatronics$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Build physical projects that sense and interact with the environment, combining electronics, mechanical parts, and Arduino code.$c$,
   $c$You might enjoy this class if you enjoy building physical projects that can sense and interact with the environment (motion, sound, lights, etc.), you are curious about combining electronics, mechanical parts, and coding, or you want significant time to work on a project of your choosing. No prior experience is required, though text-based programming experience helps. During this class, we will cover the "sense-think-act" paradigm, basic electrical circuit theory and electronics skills (breadboards, multimeters, soldering), Arduino microcontrollers, and project planning (breaking down large projects and building proof-of-concept prototypes).$c$),

  ($c$Materials Engineering$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$spring$c$, $c${10,11,12}$c$::int[], false,
   $c$Study how engineers design and test advanced materials, covering thermodynamics, heat treatment, and fabrication. Prereq: Physics.$c$,
   $c$You might enjoy this class if you are interested in how engineers design and test heat shields and what happens when they fail, you are interested in more complex materials and how they are designed and fabricated, or you are interested in engineering materials and how they are used in the real world. Helpful prior experience includes intro to physics, basic chemistry, and comfort working in the I-Lab. Topics include engineering thermodynamics, intermediate and advanced material product design, heat treatment metal chemistry, plastics, composites, metals, and other advanced material design and fabrication. Prerequisites: Physics.$c$),

  ($c$Mechanical Engineering$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$fall$c$, $c${10,11,12}$c$::int[], false,
   $c$Design and build structures and mechanisms that lift heavy loads, using various engineering materials. Prereq: Physics.$c$,
   $c$You might enjoy this class if you want to know how to build structures and mechanisms that can lift huge amounts of weight, you are interested in using engineering materials, or you enjoy designing and building spacecraft or machines like real engineers do. Comfort working in the I-Lab is helpful prior experience. During this class, we will cover understanding of mechanical movements and the theory behind them, designing and building structures or mechanical devices, and how to design and build with various engineering materials. Prerequisites: Physics.$c$),

  ($c$Product Design$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$all-year$c$, $c${10,11,12}$c$::int[], false,
   $c$A yearlong course in physical product and industrial design, from material analysis to polished models and prototypes.$c$,
   $c$You might enjoy this class if you enjoy physical product and industrial design, you want a better understanding of what makes products pleasing, functional, and appreciated, or you want to build design thinking skills toward more complete, polished models and prototypes. Basic familiarity with the shop is helpful, and knowledge of tools like the laser cutter and 3D printers is helpful but not necessary. During this class, we will cover material analysis and choice, shape studies with a focus on abstractions and cultural biases, model building, rapid iteration and sketching techniques, digital design, and sales pitches/presentations.$c$),

  ($c$Engineering, Fabrication & Design Teaching Fellowship$c$, $c$Engineering, Fabrication & Design$c$, $c$Engineering, Fabrication & Design$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired EFD course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$),

  -- ============================= ENGLISH =============================
  ($c$English 9$c$, $c$English$c$, $c$English$c$, $c$all-year$c$, $c${9}$c$::int[], false,
   $c$A full-year foundational course analyzing literary texts and constructing arguments across genres and historical periods.$c$,
   $c$In English 9, students learn to analyze literary texts and construct arguments as they develop their skills as readers, writers, collaborators, and critical thinkers. We read a variety of texts and genres, including novels, short stories, poetry, plays, and essays, that explore key values, philosophies, and aesthetics of Western culture. The fall semester is devoted to literature of antiquity and its modern echoes, and the spring semester examines literature on the topic of power and creation. Reading texts across a historical spectrum prompts students to consider how texts adopt, adapt, and deviate from recurring types of characters, plot devices, and settings. We ask how these stories imagine what it means to be human, how concepts of good and evil inform our humanity, and how the stories we tell represent various identities and cultures. Over the year, we write analytically and creatively. Texts may include The Odyssey, Frankenstein, Macbeth, and a variety of shorter poems and stories.$c$),

  ($c$English 10$c$, $c$English$c$, $c$English$c$, $c$all-year$c$, $c${10}$c$::int[], false,
   $c$A full-year course expanding reading, writing, and critical thinking, focusing on literature produced outside the West. Prereq: English 9.$c$,
   $c$Our goal in English 10 is to expand and deepen skills in reading, writing, critical thinking, and collaborative dialogue. Through encounters with a variety of literary texts, students will develop more sophisticated ways to analyze literary works and their devices; use writing mechanics, structure, and style to articulate ideas in various modes of writing; and communicate ideas to others. Another goal of English 10 is to examine and understand relations of culture, identity, and power by focusing on literature produced outside the West. Prerequisites: English 9.$c$),

  ($c$English 11$c$, $c$English$c$, $c$English$c$, $c$all-year$c$, $c${11}$c$::int[], false,
   $c$A full-year survey of American literature integrated with History 11, asking what stories Americans tell themselves. Prereq: English 10.$c$,
   $c$The particular focus in this course is the rich and varied history of American literature, from precolonial writings to the 21st century. Throughout the year, we examine and reflect on the complex interplay between literature (and other cultural forms) and the historical and political forces that shape it. The course is designed to integrate with History 11 (American History), so students make deep interdisciplinary connections in discussions and essays. The overarching question is "What stories do we tell ourselves as Americans, and why?" Readings of diverse texts encourage students to respond through three key lenses: American identities are shaped by many voices, cultures, and actions often in conflict; American literature is a product of historical dynamics that continue to resonate; and American literary forms reflect the changing notions and needs of a democratic society. Prerequisites: English 10.$c$),

  ($c$Cinema Studies$c$, $c$English$c$, $c$English$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Study, rather than make, movies—learning the art of understanding and "reading" film through analysis and criticism.$c$,
   $c$Not to be confused with a class where students focus on making movies, this course is about studying movies. With an eye toward cinema appreciation, criticism, and analysis, this class focuses on the art of understanding and "reading" film. We will spend time watching and analyzing portions of nearly 100 films (and some in their entirety). On occasion, there will be an opportunity to experiment with media creation as well, and students will create projects that utilize various cinematic techniques that we discuss together in class. Texts include short weekly readings and chapters from various filmmakers, theorists, critics, and academics, as well as the films that we will engage.$c$),

  ($c$Creative Writing$c$, $c$English$c$, $c$English$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A foundational creative writing workshop exploring fiction, nonfiction, poetry, playwriting, and hybrid texts.$c$,
   $c$This course serves as a foundational approach to the creative writing workshop, a space where students experiment with and explore their own voice while investigating a multitude of genres (fiction, nonfiction, poetry, playwriting, and hybrid texts). Not only will students have the opportunity to write, read, analyze, and respond to their classmates' writing in a workshop setting; they will study various authors' stylistic choices, literary devices, and literary elements. Students will also learn how to provide constructive feedback to their peers by engaging in class discussions and submitting written comments.$c$),

  ($c$Irish Literature$c$, $c$English$c$, $c$English$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Study the arc of the Irish literary tradition, from oral folktales to modernism to contemporary psychological realism.$c$,
   $c$Ireland, a country you can drive across in a few hours, appears to have an outsized effect upon the literary world. It is the birthplace of literary giants such as James Joyce, Oscar Wilde, and Elizabeth Bowen. No fewer than four Nobel literature laureates and six Booker prize winners have hailed from Ireland. And then there is Sally Rooney, whose recent dominance in both literature and culture has been dubbed "the Sally Rooney Effect." What is the secret to Ireland's storytelling success? To answer this question, we will study the arc of the Irish literary tradition, from oral folktales to twentieth-century modernism to contemporary psychological realism. We will also dive into Irish history and culture to better contextualize our readings.$c$),

  ($c$War and Conflict in Literature$c$, $c$English$c$, $c$English$c$, $c$fall$c$, $c${10,11,12}$c$::int[], true,
   $c$Explore 20th- and 21st-century texts on war, conflict, power, morality, trauma, and identity. Prereq: English 9.$c$,
   $c$We are told that good stories require conflict—an inflection point of tension—and yet, why do we fight? This course explores 20th- and 21st-century texts focused on the themes of war and conflict, power, morality, trauma, and identity. Specific texts will likely include All Quiet on the Western Front by Erich Maria Remarque and The Things They Carried by Tim O'Brien. Students will likely conduct interviews with veterans to design their own vignettes of the psychological, emotional, moral, and physical implications of war and conflict. Prerequisites: English 9.$c$),

  ($c$Monstrosity$c$, $c$English$c$, $c$English$c$, $c$fall$c$, $c${10,11,12}$c$::int[], true,
   $c$Consider how society and culture define and redefine the monstrous across genres from gothic to memoir. Prereq: English 9.$c$,
   $c$According to internationally recognized authority on the horror genre and monster theory John Edgar Browning, monsters are "cultural constructions of the terrible that define what it is we subconsciously fear and what it is we are told to hate or love." Definitions of the monster change over time and with each generation. Through a variety of genres from romantic to post-colonial, from gothic to horror, from fairy tales to memoir, we consider how society and culture examine earlier understandings of monstrosity and present-day fascination with the categorization of monsters. Some questions we consider include: how do authors define or redefine the monstrous? Why and how are characters made monstrous, and by whom? To what extent—through image, text, or film—do figures resist that categorization? Prerequisites: English 9.$c$),

  ($c$Memoir and Adaptation$c$, $c$English$c$, $c$English$c$, $c$fall$c$, $c${10,11,12}$c$::int[], true,
   $c$Focus on creative nonfiction and the memoir genre, investigating truth and craft in life narratives. Prereq: English 9.$c$,
   $c$The particular focus in this course is creative nonfiction, primarily the memoir genre, considering mostly contemporary texts for our investigations of truth and craft in life narratives. Throughout the semester, students reflect upon the complex interplay between memoir texts and the social, historical, geographical, and political forces that shape them, writing several formal analytical responses. Students also craft their own memoirs, informally and in formal assignments. We explore adaptations in various genres as we consider how different forms of storytelling convey elements of truthful memories and experiences. Memoirs studied may include Alison Bechdel's Fun Home, Paul Kalanithi's When Breath Becomes Air, and Alex Haley's Autobiography of Malcolm X. Note: Grade 12 students must opt into this or another English 12 elective. Prerequisites: English 9.$c$),

  ($c$19th-Century Adaptations$c$, $c$English$c$, $c$English$c$, $c$spring$c$, $c${10,11,12}$c$::int[], true,
   $c$Read 19th-century prose, poetry, and drama that was radical in form, emotion, and gender representation, and trace its modern echoes. Prereq: English 9.$c$,
   $c$First impressions of nineteenth-century literature and culture generally include descriptors such as "prudish," "repressed," "buttoned-up," and "stuffy." But, as this course shows, these texts were also at times deeply radical in their literary forms, emotional expression, gender representation, and social examinations. Through close reading of prose, poetry, drama, and literary criticism, this class considers how these texts and ideas continue to resonate in modern times. Some questions we will consider include: how do these radical texts challenge traditional views of gender, mental health, and spirituality? How do their depictions of love, inheritance, and social boundaries still echo in our cultural imagination? And in what ways can these 19th-century voices still be heard in today's conversations about identity, autonomy, and emotional expression? Prerequisites: English 9.$c$),

  ($c$Shakespeare Ever After$c$, $c$English$c$, $c$English$c$, $c$spring$c$, $c${10,11,12}$c$::int[], true,
   $c$Explore relationships in Shakespeare's plays—romance, jealousy, power, and desire—culminating in a student adaptation. Prereq: English 9.$c$,
   $c$This course explores the messy and passionate terrain of relationships in Shakespeare's plays. From swooning sonnets to emotive jealousy on stage, we analyze how the Bard portrays romantic ideals, sexual politics, heartbreak, and desire. Students investigate the roles of courtship, gender expectations, power, and language in shaping love stories, and dive into Elizabethan theatrical conventions, language, and humor as we explore some of Shakespeare's source material. We investigate critical theory as well, considering performativity and representations of gender and sexuality. As we think about our own adaptation of one of the plays (to be performed at the end of the term), we examine performance history and watch several adaptations for inspiration. Plays may include A Midsummer Night's Dream, Twelfth Night, and Much Ado About Nothing. Prerequisites: English 9.$c$),

  ($c$The Tie that Binds: Family Dynamics in Shakespeare$c$, $c$English$c$, $c$English$c$, $c$spring$c$, $c${10,11,12}$c$::int[], true,
   $c$Examine family dynamics as catalysts in Shakespeare's plays, focusing on King Lear and The Taming of the Shrew. Prereq: English 9.$c$,
   $c$There is no bond like the blood bond of family, and yet there is no hatred like that within a family. Shakespeare relies on family dynamics—suitors competing for sisters, siblings vying for possession, and cousins killing for power—as catalysts and frames for several of his plays. Shakespeare's King Lear and The Taming of the Shrew both feature sisters compared and even competing against each other. Looking at King Lear, we ask whether Lear's daughters are the causes or the victims of this tragedy. While The Taming of the Shrew is a comedy, its dark undertones reveal compelling family drama, and we ask how Katherina and Bianca's relationship frames the taming narrative. We explore gender theory and Freudian theory as we read both plays, and view adaptations including 10 Things I Hate About You and excerpts from Succession. Prerequisites: English 9.$c$),

  ($c$Women in Literature$c$, $c$English$c$, $c$English$c$, $c$spring$c$, $c${10,11,12}$c$::int[], true,
   $c$Study foundational texts by and about women and their long-term influence, culminating in a dramatic adaptation. Prereq: English 9.$c$,
   $c$Women in Literature begins with the careful, in-depth reading of one or more classic literary texts that help us understand the social, historical, creative, and critical contexts of women writers through the ages. The semester then explores how the literary values and long-term legacies of a set of foundational texts and ideas have influenced writing by and about women over the centuries. Students explore the original and ongoing reception of works composed in a variety of genres and across geographic, political, and historical environments. As readers and interlocutors, they co-create a conversation about women's literary history and join contemporary critical debates about representation and self-representation. The semester concludes with students writing and producing a dramatic adaptation of a classic text. The course builds explicitly on skills developed in English 9, 10, and 11. Prerequisites: English 9.$c$),

  ($c$English Teaching Fellowship$c$, $c$English$c$, $c$English$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired English course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$),

  -- ============================= HISTORY =============================
  ($c$Asian America$c$, $c$History$c$, $c$History$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Examine the complexity and diversity of the Asian American immigration experience and fight for equal recognition.$c$,
   $c$Asian Americans have been in the fabric of America since its beginnings, and yet have been considered perpetual foreigners. Despite the variety of laws targeted at Asian immigration, immigrants have found a way to enter, to settle and build, to become American. This course examines the complexity and diversity of the Asian American immigration experience, the role Asian Americans have played in fighting for equal protection and recognition as Americans, and the modern challenges of being considered perpetual foreigners and a model minority. Because this course is designed for 9th and 10th graders, upperclassmen will be expected to complete a more advanced research project.$c$),

  ($c$Capitalism & Apocalypse$c$, $c$History$c$, $c$History$c$, $c$fall$c$, $c${11,12}$c$::int[], false,
   $c$A discussion-based history of capitalism as a system of power, culminating in original student research. Prereq: History 10.$c$,
   $c$Our goal in this class is not to assess some false dichotomy of "capitalism good" or "capitalism bad," but rather to understand how different regimes of capitalism become embedded in our daily lives. The title gestures toward the phrase "it is easier to imagine the end of the world than the end of capitalism." To tell a history of capitalism is to push against the notion of a static present and tell a story of change and contest. Capitalism is conceived as a system of power, one that operates most effectively when that power has become invisible, masked behind a veneer of common-sense understanding. The course examines the cultural processes—deploying languages of race, gender, class, and respectability—by which these systems of power are rendered invisible and visible. The class is discussion-based, with readings in history and theory, and culminates with original student research around moments of transition in American capitalism. Prerequisites: History 10.$c$),

  ($c$Existentialism$c$, $c$History$c$, $c$History$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Read existential philosophy and literature on alienation, anxiety, nihilism, absurdity, and the self.$c$,
   $c$What do we talk about when we talk about existentialism, and why do we still talk about it at all? In this course, we read texts in existential philosophy and literature with special emphasis on themes such as alienation, anxiety, nihilism, absurdity, and the self. We examine the works of important existentialist thinkers on the meaning of life, the nature of individuality, freedom, and emotional integrity. The majority of the course focuses on philosophy, beginning with Søren Kierkegaard and Friedrich Nietzsche, then turning to Martin Heidegger, Jean-Paul Sartre, Simone de Beauvoir, and Frantz Fanon. We situate this movement in its historical contexts—two world wars, the Cold War, decolonization—and on matters of race, class, and gender. In the final unit, we trace the influence of existentialist philosophy on literature, film, and popular culture. Students write weekly discussion posts, two short essays, and complete a final research project.$c$),

  ($c$History 9 - World to 1500$c$, $c$History$c$, $c$History$c$, $c$all-year$c$, $c${9}$c$::int[], false,
   $c$A full-year survey of major themes in pre-modern world history, from the earliest civilizations to the start of the modern period.$c$,
   $c$This course covers major themes and developments from pre-modern world history. The course starts with a look at the earliest civilizations and ends with an exploration of several cultural conflicts that defined the start of the modern period. Although the course covers a great deal of pre-modern global history, it is not intended as an exhaustive survey of every event or development from this era. Many but not all of the important historical moments from the ancient and medieval periods will be covered.$c$),

  ($c$History 10 - Modern World$c$, $c$History$c$, $c$History$c$, $c$all-year$c$, $c${10}$c$::int[], false,
   $c$A full-year study of the modern world since 1500, developing source analysis and historical argument. Prereq: History 9.$c$,
   $c$Students in History 10 develop skills in source analysis and historical argument by writing papers, presentations, and exhibits on the modern world since 1500. We begin by examining the world trading system that spanned from the Americas to European empires to Ming China in the sixteenth century, focusing on social, economic, and political systems like mercantilism and capitalism. We explore these systems through the commodities they delivered for European consumers and through the experiences of enslaved Africans who produced them. We end the fall by exploring the Atlantic Revolutions and the Industrial Revolution. In the spring we shift to the crises of the twentieth century, building causal arguments from timelines, presenting primary sources from the First World War, and analyzing the rise of fascism and the anticolonial struggles that followed. We end with contemporary history to understand the origins of our present day. Prerequisites: History 9.$c$),

  ($c$History 11 - US History$c$, $c$History$c$, $c$History$c$, $c$all-year$c$, $c${11}$c$::int[], false,
   $c$A full-year survey of the major forces shaping the United States, framed by key analytical questions. Prereq: History 10.$c$,
   $c$United States History is designed to provide students with a survey of the major forces which have shaped our country and to incorporate deeper contemplation of specific eras and historical schools of thought. Students explain how past events helped shape modern society while appreciating the complex connections between those events. In doing so, students engage with three key questions: Are capitalism and democracy complementary or contradictory? Is the American state a vehicle for repression or liberation? Globally, have US actions lived up to or contradicted the ideals of freedom and democracy? Rather than answering these conclusively, we use them as an analytical framework across varied case studies. Students deepen their expertise in areas of individual interest through varied readings, independent and collaborative research, and regular presentations to one another. Prerequisites: History 10.$c$),

  ($c$Ideas in Political Economy$c$, $c$History$c$, $c$History$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$An intellectual history of political economy, reading influential thinkers on markets, class, and power from the 18th to 21st century.$c$,
   $c$For as long as economists have studied how the economy works, philosophers and revolutionaries have clashed over how it ought to work. Adam Smith described a new system of markets that could empower common people; Karl Marx condemned that system for shackling workers to machines; and thinkers debate the compatibility of economic growth and environmental sustainability today. In this course we explore those debates in political economy by reading the most influential thinkers on markets, class, and power, from the eighteenth to the twenty-first century. This is a class in intellectual history in which we analyze ideas in their context, and it allows us to assess which theories from the past can help us understand the present. We dive into historically significant texts and spend time with the authors' arguments to understand and evaluate the evidence, assumptions, and convictions that guide them. No background in economics is required.$c$),

  ($c$International Relations$c$, $c$History$c$, $c$History$c$, $c$spring$c$, $c${11,12}$c$::int[], false,
   $c$Study the major theories of international relations and case studies from 1945 to the present. Prereq: History 10.$c$,
   $c$Why has war been such a dominant force in human history? Is the world simply a chaotic collection of self-interested states, or does an international society exist that might one day eradicate global conflict? Why do some states fail and degenerate into ethnic and sectarian strife? Can economic integration create peace? These are some of the central questions of international relations, a branch of political science. In this course we study the major theories of the discipline, including key works from the realist, liberal, and constructivist schools, and examine case studies from 1945 to the present day, spanning Russia, Europe, Asia, Africa, and the Americas. We then look to our current geopolitical moment and seek to understand what new global order is emerging. This course features student collaboration within seminar-style classes; students must be ready to present and discuss mature material, including real-time international issues. Prerequisites: History 10.$c$),

  ($c$Religion and Modernity$c$, $c$History$c$, $c$History$c$, $c$fall$c$, $c${10,11,12}$c$::int[], false,
   $c$Use history and the study of religion to explore religion's changing place in public life and private belief. Prereq: History 9.$c$,
   $c$Is religion retreating from public life or becoming more important to people's political views? Are people losing faith, or putting that faith in technology? What do people mean when they say they are "spiritual but not religious"? These questions confront us today and have recurred throughout modern history as developments in science and politics challenge the importance of religion. We approach these questions by turning to history and applying concepts from the study of religion. The class begins with the Protestant Reformation within Christianity and its radical reassessments of private belief and new relationships between church and state. We then study the range of church-state relationships around the world and the new technologies that challenge some beliefs and extend the reach of others. Students read and discuss historical primary documents and contemporary theoretical works in every class, and do writing, classroom teaching, and independent research in a topic of choice. Prerequisites: History 9.$c$),

  ($c$Sociocultural Anthropology: Culture, Exchange, Technology Studies$c$, $c$History$c$, $c$History$c$, $c$fall$c$, $c${10,11,12}$c$::int[], false,
   $c$An introduction to cultural anthropology over the last 125 years, emphasizing "thick description" of cultural practices. Prereq: History 9.$c$,
   $c$In this course, students receive an introduction to the development of the field of cultural anthropology over the last 125 years. A social science, anthropology is the study of humans and their culture, emphasizing "thick description" of cultural practices, such as exchange, inequality, violence, gender, kinship, mobilities, environment, and ritual. It is a large and diverse field, with practitioners using methods including archaeology, immersive ethnographic fieldwork, the study of cultural artifacts, the microanalysis of language practices, and interviews. The course begins with the origins of systemic ethnographic fieldwork and the rise of anthropology in the early 20th century, then engages with 21st-century anthropologists working on complex objects and cultures (climate change, data algorithms, capitalism, food systems). Students will do a bit of fieldwork themselves. This course suits students interested in social science closer to the humanities and those wanting a more systemic, granular approach to the study of culture. Prerequisites: History 9.$c$),

  ($c$What Is Philosophy?$c$, $c$History$c$, $c$History$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A broad survey of philosophy covering metaphysics, epistemology, ethics, aesthetics, and social and political philosophy.$c$,
   $c$Why does anything exist? Why can't we turn around in time as we can in space? Is time even real? What is a society, and how should it be organized? Is justice something other than the interests of the powerful? Is democracy better than other political systems? In this course we consider how philosophers in a variety of contexts, from the ancient world to the present, have thought about such questions. You will have the chance to think, talk, and write about these matters and other problems of interest to you. This course is intended to be a broad survey of philosophy and covers topics in metaphysics, epistemology, ethics, aesthetics, and social and political philosophy.$c$),

  ($c$Work Ethics: A History$c$, $c$History$c$, $c$History$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A history of work ethics, examining how the human relationship with work has evolved over time and across space.$c$,
   $c$Studs Terkel introduced his collection of interviews from working people during the 1970s by stating that "This book, being about work, is, by its very nature, about violence—to the spirit as well as to the body." His remarks hint at the relationship we often assume between work and pain. But does work have to hurt for it to be valid? How do we measure the value of work? Is labor only work when it is paid? Writing at the turn of the 20th century, Max Weber described the Protestant work ethic as the mindset that gave rise to modern capitalism. But there have been other ethics of work. This class is a history of work ethics with the goal of examining how the human relationship with work has evolved over time and across space, looking at agrarian societies, the relationship between leisure and work, and how ideas of work became intertwined with race and gender. At its core, this course explores how ideas become embedded within society as common-sense beliefs.$c$),

  ($c$History Teaching Fellowship$c$, $c$History$c$, $c$History$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired history course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$),

  -- ============================= INTERDISCIPLINARY =============================
  ($c$Art History: A Survey$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A survey of art history from Sumer to New York City, investigating famous and lesser-known art movements.$c$,
   $c$What makes something art? How does art reflect the history of ideas? Can art exist independently, without referencing art history? These are the core questions of our course, which takes us from Sumer to New York City, from 3000 BC to our current streets, and from a tiny antler carving of a reindeer to a French artist whose performance piece was to throw his payment of gold bullion into the river Seine. Along the way we investigate the most famous art movements, such as Neoclassicism, Baroque, and Abstract Expressionism, as well as some lesser-known moments in art history. We write odes to paintings, virtually explore dozens of museums together, create thematic timelines, and discuss quite a lot of art. Students should be ready to write a few analyses of art pieces or movements.$c$),

  ($c$Psychological Disorders: Body, Mind, and Culture$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$fall$c$, $c${11,12}$c$::int[], false,
   $c$Explore psychiatric disorders through biological, cognitive, social, and cultural lenses. Prereq: Intro to Psychology (or relevant advanced coursework for seniors).$c$,
   $c$In this course we explore what used to be called "abnormal psychology," the study of psychiatric disorders. We look generally at definitions, descriptions, and diagnostic criteria of mental health conditions before digging more deeply into three disorders, which may include anxiety, depression, PTSD, eating disorders, borderline personality disorder, and schizophrenia. To understand each condition, we consider its etiology, symptoms, and treatment through several lenses—biological, cognitive, social, and cultural—adopting a multi-factorial and interactionist approach. We also examine culture-bound conditions such as susto, ghost sickness, resignation syndrome, and hikikomori. The course is inquiry-based, with readings, videos, class discussion, and speakers. Assessments include an individual exploration of a disorder and a group project on treatment, with core texts including Crazy Like Us: The Globalization of the American Psyche and the latest edition of the DSM. Prerequisites: Psychology 101; seniors who have taken advanced biology, anthropology, or online/summer psychology classes may also enroll.$c$),

  ($c$Comparative Literature: Art and War$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Examine literary and artistic responses to WWII trauma through a comparative lens, introducing comparative literature.$c$,
   $c$German philosopher Theodor Adorno famously wrote, "To write poetry after Auschwitz is barbaric." What are the ethics of writing about atrocity? Who can speak for the dead, and what does it mean to listen to them? This course examines these difficult questions through a comparative lens, looking at various literary and artistic responses to three forms of generational trauma created by World War II: the Holocaust in Eastern Europe, the Japanese American internment in the United States, and the atomic bombings of Hiroshima and Nagasaki. By reading works—including literature, films, graphic novels, painting, and photography—alongside each other, this course asks how art and war are related and opposed to each other. In this way, the course introduces students to the discipline of comparative literature, which identifies literary, historical, and theoretical connections across texts from different languages, cultures, and media. Projects may include short essays, creative writing, oral interviews, and independent research.$c$),

  ($c$Environmental Humanities$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], true,
   $c$Use humanistic questions to address environmental problems, studying storytelling and climate change across disciplines.$c$,
   $c$Environmental Humanities employs humanistic questions about meaning, culture, values, ethics, and responsibilities to address pressing environmental problems, helping to bridge traditional divides between the sciences and the humanities. This interdisciplinary class looks at storytelling and climate change through the study of environmental philosophy, environmental history, ecocriticism, cultural anthropology, and ecosemiotics. Some questions we look at include: whose voice has been centered in the telling of climate change? Whom have we left out of the conversation? How can we tell a convincing story in the face of climate science denial? And what are some new mediums to tell an impactful story in the future? The class contains six modules: Language and Narration, Imperialism and Colonialism, Indigenous Knowledge, Nature, Climate Migration, and the Anthropocene and the Future.$c$),

  ($c$Design + Systems Thinking: Building a Music Festival [Not Running in 2026-27]$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$spring$c$, $c${11,12}$c$::int[], true,
   $c$An upper-level elective co-developing an interdisciplinary festival project through design and systems thinking. Not running in 2026-27.$c$,
   $c$This course is for those who want to explore optimal human impact with consideration to liberation through melody, catharsis through dance and rhythm, and the healing that happens through the artist-fan connection. This upper-level elective provides the opportunity to co-develop an interdisciplinary project with advanced exploration of both design and systems thinking. A deeper understanding of human-, empathy-, and innovation-driven design thinking and the analytical, structure-based approach of systems thinking equips students to build something marvelous collaboratively. Throughout the course, small groups leverage different disciplines to deconstruct festival components including budget, venue, food, art, marketing, and the artists involved. Students practice collaboration, design thinking, budgeting, and communication through group brainstorms, criteria-based writing, design projects, a negotiation simulation, and frequent project check-ins with peer critique. The course culminates in a festival pitch presentation. Note: This course is not running in 2026-27.$c$),

  ($c$Free Block$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$both$c$, $c${11,12}$c$::int[], true,
   $c$An approved free block in the schedule for rising juniors and seniors, arranged with a college counselor or learning specialist.$c$,
   $c$While not available to request in the elective preference form, rising juniors and seniors are required to speak to a college counselor or learning specialist to be approved for a free block in their schedule. When approved, the student will email Ryan, copying the college counselor with whom they spoke and, as applicable, the learning specialist.$c$),

  ($c$Gender and Sexuality$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Study how people navigated gender and sexuality across regions and time periods through primary sources and critical theory.$c$,
   $c$How has masculinity been defined in different regions and time periods? How did people in Ancient Greece and China conceptualize queerness? What is a TERF and how does that relate to the history of feminism? What lies at the intersection of race, class, and gender? This course is for anyone who has ever experienced gender and sexuality—which is to say, everyone. We look at how people navigated individual identity and social expectations around gender and sexuality across a number of case studies: from the ancient Mediterranean to the "Wild West" of the 19th century, to queer and straight life in 1930s New York City, to contemporary conceptualizations of identity and sexuality outside America. Homework and classwork focus on reading and discussing primary sources, historical media, and queer and feminist critical theory. Assessments are primarily short reflective or analytical writing pieces and individual research projects, ending with original research into a case study of the student's choosing.$c$),

  ($c$Independent Study$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$both$c$, $c${11,12}$c$::int[], true,
   $c$An application-only opportunity to pursue a deep dive into an academic course of study of the student's choosing.$c$,
   $c$Independent study is an opportunity for students to pursue a deep dive into an academic course of study of their choosing. This research block cannot replace an existing course taught at Nueva. Rather, it is either an extension of a student's interest that may be inspired by a course (e.g., art history, but the student wishes to study Japanese woodblock in particular) or a passion which a student wants to explore in academic detail (e.g., Russian literature). This course is by application only; projects are approved by the Independent Course of Study Coordinator.$c$),

  ($c$Independent Study: Internship$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$both$c$, $c${11,12}$c$::int[], true,
   $c$Transcript credit for juniors and seniors engaging in meaningful, experiential learning with an outside organization.$c$,
   $c$The Independent Study: Internship is an opportunity for Nueva juniors and seniors to receive transcript credit for engaging in meaningful, experiential learning with an organization outside of the curricular offerings. Students may elect to take it during the fall or spring semester, or both. The credit must be in place of an elective or during a free period; students may not receive it on top of a full course load. In addition to meeting expectations set by a manager, students should plan on meeting with the internship coordinator and other internship students regularly throughout the semester. Internship requirements include a minimum of 4 hours per week of work (paid or unpaid) and that the position provides learning not possible through existing Nueva curricular offerings. Interested students should contact the internship coordinator before the second and final add/drop period closes.$c$),

  ($c$Intro to Psychology$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$fall$c$, $c${10,11,12}$c$::int[], false,
   $c$An introduction to psychology, examining behavior through biological, cognitive, and social-cultural factors.$c$,
   $c$Does digital technology change our thinking? Why do art and music affect people differently? Can we predict who a person will be attracted to? How does a person form an identity? Can trauma be inherited? What are the roots of prejudice? Answers to questions like these can be found in the field of psychology. Contemporary psychology posits that the way humans act and think is shaped by the interaction among biological, cognitive, and social-cultural factors. In this elective, students critically examine research related to certain behaviors; learn fundamental theories such as schema theory and social identity theory; write analytical essays; participate in seminar-style discussions; and create individual and group projects such as podcasts, games, and films on topics of their choice. By the end of the course, students have a good grounding in the field for future study, understand the strengths and limitations of studying human behavior, and develop an appreciation for the ways humans act and think.$c$),

  ($c$Intro to Speech and Debate$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$both$c$, $c${9,10,11,12}$c$::int[], true,
   $c$The entry point for Nueva's competitive debate program, covering research, casewriting, and speaking skills.$c$,
   $c$This course is the entry point for Nueva's competitive debate program: extemporaneous speaking, impromptu speaking, parliamentary debate, public forum debate, and world schools debate. Introductory students learn basic research, casewriting, and speaking skills required for novice competition. Experienced students mentor introductory students and work on advanced theory and philosophical positions, strategy, and audience-tailored performance choices. All students compete in at least one interscholastic tournament each semester, though many more are offered. Students with no prior competition experience in at least one target event are highly encouraged to take the elective concurrently with joining the extracurricular team.$c$),

  ($c$Journalism$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A yearlong newspaper-production course covering news, feature, opinion, sports, and culture writing plus layout and editorial design.$c$,
   $c$In this yearlong course, students read and write a range of newspaper writing styles, including news, feature, opinion-editorial, sports, and culture. We learn to write for different audiences and purposes, practice revision, and create compelling and meaningful stories that meet standards of accuracy, grammar, style, and journalism ethics. This is a writing and newspaper-production course that explores a variety of storytelling techniques, emphasizes the importance of research and interviewing, and teaches layout and editorial design.$c$),

  ($c$Linguistics: Logic and Language$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Explore language as a definitively human trait, bridging the humanities and cognitive science through linguistics.$c$,
   $c$From the age-old search for the perfect imaginary language to the dreams of consistency springing from logic, we explore the components of this definitively human trait. Do we think in a language? What constitutes a language anyway? How different is Swahili from Sanskrit or Linear B from Klingon? What language do bilingual children dream in? Are there nonhuman languages? How do computers speak? This course seeks to bridge the "two cultures," with language as the scaffold. On one hand, language is the quintessential human attribute, offering a unique perspective into the human condition; we explore the formal components of linguistics in historical, cultural, and literary contexts. On the other hand, language is a paramount window into the mind and how it arises from the brain, subject to evolutionary forces and now the primary vehicle for experiencing artificial intelligence. Students draw on their own linguistic experiences to explore this indispensable tool for making sense of the world.$c$),

  ($c$Philosophy of Consciousness and Personhood$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A reading-and-discussion seminar on consciousness, mind, personhood, and their ethical, medical, and legal implications.$c$,
   $c$This course is a reading-and-discussion seminar centered around the questions: What is consciousness? What makes it difficult to study? Is the mind just the brain? Is consciousness an illusion, and what would that mean? Is our personhood and identity dependent on consciousness? How do these philosophical questions affect ethical, medical, technological, and legal issues? We read works in philosophy, cognitive and neuroscience, and science fiction, such as works by Churchland, Nagel, Chalmers, and Asimov; we discuss ideas such as artificial intelligence, animal testing, split-brain patients, and multiple personality disorder. There will be weekly readings, required discussion points, a mid-semester project, and a final essay.$c$),

  ($c$Psychology and Memory$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$spring$c$, $c${11,12}$c$::int[], false,
   $c$A psychology elective on reconstructive memory theory and the implications of memory's unreliability. Prereq: Intro to Psychology (or G12 with permission).$c$,
   $c$This psychology elective centers on reconstructive memory theory and explores the implications of memory's inherent unreliability in many contexts. For each aspect of memory we study, we look at the biological, cognitive, social, and cultural factors that contribute to the creation, consolidation, alteration, and loss of memory. We also allow the psychological study of memory to mingle with its portrayal in literature and art. We examine causes and consequences of conditions that affect memory, such as Alzheimer's and trauma/PTSD, and how these are portrayed culturally. We veer into collective memory and the psychological purpose of commemoration, the function of nostalgia, the effects of rumination, and the effects of digital technology on memory. Overall, this is an examination of all things memory, from the biopsychosocial model to literature to cultural anthropology, with diverse project-based assessments. Prerequisites: Intro to Psychology, or grade 12 students with permission of instructor.$c$),

  ($c$Research in Psychology$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$spring$c$, $c${10,11,12}$c$::int[], true,
   $c$A follow-up to Intro to Psychology in which students design and run their own quantitative and qualitative studies. Prereq: Intro to Psychology.$c$,
   $c$Can human behavior be quantified? What is the best way to study how and why humans do what they do? In this follow-up to Psychology 101, students continue to examine the biological, cognitive, and sociocultural roots of behavior and mental processes, this time with two new topics: thinking and decision making (with a focus on Daniel Kahneman's two-system theory) and child development (Piaget and Vygotsky, brain development frameworks, and environmental factors that threaten normal development). Unlike in Psych 101, students become the researchers, designing and running two complete studies of their own: one quantitative laboratory experiment and one qualitative study using observation and/or interview methods. They learn to interpret their results and write a journal-style article. The semester ends with students applying their knowledge to a real-world issue. Prerequisites: Intro to Psychology.$c$),

  ($c$Translation Studies$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$An introduction to translation studies, examining how translation shapes national, cultural, and linguistic identities. Prereq: Chinese 2, Japanese 2, Spanish 2, or equivalent.$c$,
   $c$This course is an introduction to the exciting and interdisciplinary field of translation studies, which examines not only how words and texts are translated but also how they function in the production and transformation of national, cultural, and linguistic identities. The course encourages students to think critically and comparatively about how translation shapes, if not skews, our understanding of other peoples, languages, and cultures. Beginning with the question "What is translation?", this course covers foundational theories and problems of translation before turning to case studies of literature in translation (prose and poetry). The course also examines translation as a metaphor in various films, stories, and other texts. At the end of the course, students produce a translation of their own. Prerequisites: Chinese 2, Japanese 2, Spanish 2, or the equivalent.$c$),

  ($c$Yearbook Media Production$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A yearlong course producing Nueva's annual yearbook, building skills in design, journalistic writing, and photography.$c$,
   $c$This yearlong course produces Nueva's annual yearbook. Yearbook offers students an exciting opportunity to further their creative interests in writing, design, and photography while acquiring highly transferable skills in journalism, print production, and visual storytelling. Skills covered include digital design (layout, theme development, and Adobe InDesign), journalistic writing (features, captions, and interviews), and digital photography (composition, shutter rate, depth of field, and Adobe Photoshop). This class emphasizes both collaboration and student leadership; students are expected to invest fully by meeting all deadlines, actively participating, fulfilling their duties as staff or editors, and contributing to the overall advancement of the yearbook theme and content.$c$),

  ($c$Interdisciplinary Teaching Fellowship$c$, $c$Interdisciplinary$c$, $c$Interdisciplinary$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$),

  -- ============================= LANGUAGES =============================
  ($c$Chinese 1$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A yearlong beginning Chinese course focusing on oral communication, pinyin, and simplified characters, aiming for Novice Mid proficiency.$c$,
   $c$The Chinese program provides students opportunities to incorporate communication, collaboration, and technology skills in learning the Chinese language and its rich culture. In Beginning Chinese, students focus on culturally appropriate oral communication in Mandarin while utilizing pinyin to facilitate sound transcription of the tonal language. Reading, writing, and typing in simplified characters (with references to traditional counterparts) progress in parallel with oral skills. Through each thematic unit—starting from self, family, and school and expanding to community and world—students learn vocabulary, language patterns, dialogues, and culture topics, create group presentations, and form conversations for real-life scenarios. Foundational information of geography, history, pronunciation, classroom expressions, and Chinese characters are introduced and reiterated across units. Students aim to achieve Novice Mid proficiency across interpretive, interpersonal, and presentational communications (ACTFL standards).$c$),

  ($c$Chinese 2$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A yearlong course expanding Chinese vocabulary and sentence structures, aiming for Novice High proficiency. Prereq: Chinese 1.$c$,
   $c$The Chinese program provides students with opportunities to incorporate communication, collaboration, and technology skills in learning China's language and its rich culture. Chinese 2 starts with an expansion of vocabulary and sentence structures built on top of Chinese 1 content through dialogue creation, reading, listening, and writing. This course completes 5 units from Integrated Chinese Level 1 (Part 1) and covers topics including making an appointment, studying Chinese, shopping, transportation, and weather. In addition to colloquial Mandarin, students are exposed to more formal written language with stories and songs. While advancing in reading and creative writing, students dive deeper into cultural comparisons and 21st-century world citizenship through group projects and comic/drama production. Students aim to achieve Novice High proficiency across interpretive, interpersonal, and presentational communications (ACTFL standards). Prerequisites: Chinese 1 or equivalent.$c$),

  ($c$Chinese 3$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A yearlong course centered on decision-making and planning themes, aiming for Intermediate Low proficiency. Prereq: Chinese 2.$c$,
   $c$The Chinese program provides students with opportunities to incorporate communication, collaboration, and technology skills in learning the Chinese language and its rich culture. The Level 3 Chinese course is composed of themes and units about decision-making and planning. Topics include directions, seeing a doctor, dating, living space, sports, and travel. The course roughly completes 5 units from Integrated Chinese Level 1 (Part 2). Correlated cultural topics are introduced with each unit for exploration and comparison. In addition to new vocabulary and sentence structures, students are further immersed in an authentic environment through Chinese short stories, songs, news segments, TV series, and animated videos. Students aim to achieve Intermediate Low proficiency across interpretive, interpersonal, and presentational communications (ACTFL standards). Prerequisites: Chinese 2 or equivalent.$c$),

  ($c$Chinese 4$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$The fourth year of Chinese, equipping students with more complex expressions and styles, aiming for Intermediate Mid proficiency. Prereq: Chinese 3.$c$,
   $c$Chinese 4 is the fourth year of the Chinese program at Nueva Upper School. Its primary focus is to continuously equip students with expressions, styles, and language structures of higher complexity in both oral and written communication for various purposes. Students learn to differentiate between speaking and writing the choice of words and phrases essential for higher-level social functions. This course allows students to incorporate communication, collaboration, and technology skills in learning the Chinese language and its rich culture. Topics studied this year are travel, at the airport, starting a new semester, at a restaurant, shopping, and choosing classes. This course prepares students to achieve Intermediate Mid proficiency across interpretive, interpersonal, and presentational communications (ACTFL standards). Prerequisites: Chinese 3 or equivalent.$c$),

  ($c$Chinese 5: Current Events & Film$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Explore contemporary Chinese culture and society through current events and film, aiming for Intermediate High proficiency. Prereq: Chinese 4.$c$,
   $c$The primary focus of Chinese 5 is to further explore topics related to contemporary Chinese culture, economic growth, social challenges, and modernization in order to develop a wider and deeper understanding of Chinese-speaking communities and to bridge the differences between the East and the West. Students continue to lead discussions in Chinese, brainstorming solutions for issues of interest and debating various topics through current events and contemporary films. We focus on current events in the first semester and films in the second semester. This course prepares students to achieve Intermediate High proficiency across interpretive, interpersonal, and presentational communications (ACTFL standards). Prerequisites: Chinese 4 or equivalent.$c$),

  ($c$Chinese Literature & Advanced Research$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$An advanced course in literary analysis and research on the Chinese diaspora, aiming for Intermediate High proficiency. Prereq: Chinese 4.$c$,
   $c$This advanced course is designed for students aiming to dive deeper into literary analysis and advanced research on topics involving the Chinese diaspora. In the fall semester, the course focuses on close readings of selected literature from different historical and literary periods, especially contemporary. Through close reading and discussion, students understand the socio-cultural reality in which the texts were written and their contemporary relevance. In the spring semester, students conduct in-depth research in the target language and present it in various forms, such as an academic paper or panel discussion. Students pursue passion-driven research on topics including history, geopolitical conflict, cultural phenomena, social justice, and environmental citizenship in the Chinese diaspora. The focus is for students to become self-sufficient using Chinese as a research tool in an academic context, aiming for Intermediate High proficiency (ACTFL standards). Prerequisites: Chinese 4 or equivalent.$c$),

  ($c$Japanese 1$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A yearlong introductory Japanese course developing reading, writing, speaking, and listening, aiming for Novice Mid proficiency.$c$,
   $c$Japanese 1 is a year-long introductory course that develops students' reading, writing, speaking, and listening skills through a systematic introduction and integration of grammar, vocabulary, kanji, and culture. Using a communicative approach informed by the five C's of foreign language education as defined by ACTFL (Communication, Cultures, Connections, Comparisons, and Communities), this course enables students to achieve Novice Mid proficiency in Japanese. In assignments and assessments, equal emphasis is given to the three basic modes of communication: the interpersonal, the interpretive, and the presentational.$c$),

  ($c$Japanese 2$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Builds on Japanese 1 to develop skills through grammar, vocabulary, kanji, and culture, aiming for Novice High proficiency. Prereq: Japanese 1.$c$,
   $c$Building on Japanese 1 or the equivalent, Japanese 2 is a yearlong course that develops students' reading, writing, speaking, and listening skills in Japanese through a systematic introduction and integration of grammar, vocabulary, kanji, and culture. Using a communicative approach informed by the five C's of foreign language education as defined by ACTFL, this course enables students to achieve Novice High proficiency in Japanese. Assignments and assessments focus on the three basic modes of communication: the interpersonal, the interpretive, and the presentational. Prerequisites: Japanese 1 or equivalent.$c$),

  ($c$Japanese 3$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Builds on Japanese 2, aiming for Intermediate Low proficiency through grammar, vocabulary, kanji, and culture. Prereq: Japanese 2.$c$,
   $c$Building on Japanese 2 or the equivalent, Japanese 3 is a yearlong course that develops students' reading, writing, speaking, and listening skills in Japanese through a systematic introduction and integration of grammar, vocabulary, kanji, and culture. Using a communicative approach informed by the five C's of foreign language education as defined by ACTFL, this course enables students to achieve Intermediate Low proficiency in Japanese. In assignments and assessments, equal emphasis is given to the three basic modes of communication: the interpersonal, the interpretive, and the presentational. Prerequisites: Japanese 2 or equivalent.$c$),

  ($c$Japanese 4$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Builds on Japanese 3, aiming for Intermediate Mid proficiency through grammar, vocabulary, kanji, and culture. Prereq: Japanese 3.$c$,
   $c$Building on Japanese 3 or the equivalent, Japanese 4 is a yearlong course that develops students' reading, writing, speaking, and listening skills in Japanese through a systematic introduction and integration of grammar, vocabulary, kanji, and culture. Using a communicative approach informed by the five C's of foreign language education as defined by ACTFL (Communication, Cultures, Connections, Comparisons, and Communities), this course enables students to achieve Intermediate Mid proficiency in Japanese. In assignments and assessments, equal emphasis is given to the three basic modes of communication: the interpersonal, the interpretive, and the presentational. Prerequisites: Japanese 3 or equivalent.$c$),

  ($c$Adv. Topics in Japanese$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], true,
   $c$A yearlong topics-based advanced Japanese course aiming for Intermediate High proficiency; a rotating course that may be taken multiple times. Prereq: Japanese 4.$c$,
   $c$Building on Japanese 4 or the equivalent, Advanced Topics in Japanese is a yearlong course that develops students' skills through a topics-based study of grammar, vocabulary, kanji, and culture. Using a communicative approach informed by the five C's of foreign language education (ACTFL), this course enables students to achieve Intermediate High proficiency. Assignments emphasize the interpersonal, interpretive, and presentational modes: students do skits and speeches, read and analyze authentic materials, and discuss advanced topics in Japanese. Topics change yearly and have included geography, robots and technology, food, religion, pop culture, education, history, literature and poetry, performing arts, environmental issues, the atomic bomb, and urban studies. The course uses advanced textbooks and multimedia such as Genki 2, Adventures in Japanese, Tobira, and Quartet. Students can deepen their skills through an optional trip to Japan in the spring. This is a rotating topics course, so it may be taken multiple times for credit. Prerequisites: Japanese 4 or equivalent.$c$),

  ($c$Spanish 1$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A yearlong course building a foundation in Spanish across interpersonal, presentational, and interpretive skills.$c$,
   $c$Spanish 1 is designed to build a foundation in the Spanish language, with a focus on developing students' skills in interpersonal communication, presentational speaking and writing, and interpretive reading and listening. Comprehensible and repetitive exposure to high-frequency structures is provided through visuals, physical activities, stories, readings, and conversations about students and their lives, while making space for comparisons and connections with the cultures of Spanish-speaking countries. Students understand the benefits of learning a second language and the skills needed for successful acquisition, broadening perspectives about communities near and far. They learn to introduce themselves, describe their passions and interests, and describe themselves and their friends. As they explore cultural traditions related to homes and families, students describe different types of families, roles, and activities. As the year progresses, students construct and respond to questions and become storytellers, retelling and adapting real and imaginary stories.$c$),

  ($c$Spanish 2$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A yearlong course continuing Spanish acquisition with expanded vocabulary and grammar. Prereq: Spanish 1.$c$,
   $c$The Spanish 2 course is designed for students to continue developing the skills and practices needed for the successful acquisition of the Spanish language, broadening perspectives about communities both near and far. Students continue their study of Spanish by further expanding their knowledge of key vocabulary topics and grammar concepts. They comprehend listening and reading passages more fully and express themselves more meaningfully and with greater spontaneity in both speaking and writing. Prerequisites: Spanish 1 or equivalent.$c$),

  ($c$Spanish 3$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A yearlong course strengthening grammar and fluency through conversation, readings, and cultural topics. Prereq: Spanish 2.$c$,
   $c$Students in Spanish 3 review and strengthen their understanding of essential Spanish grammar and build on the foundation of previous courses. They expand their vocabulary and increase fluency through frequent conversational practice, presentations, readings, creative projects, and research on cultural topics. Throughout the year, students progress through the ACTFL standards, increasing their ability to express needs and wishes, write cohesive passages, and present clearly using complex sentences. Through individual and collaborative activities, students understand how life experiences shape identity, discuss cultural celebrations, consider the relationship between life and the arts, delve into social justice issues, and describe environmental challenges. Students master the preterit, imperfect, and present perfect tenses while implementing the present subjunctive, review the future and conditional tenses, and learn to express desires and give instructions using the imperative. Prerequisites: Spanish 2 or equivalent.$c$),

  ($c$Spanish 4$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A yearlong thematic course refining oral and written Spanish, conducted entirely in Spanish. Prereq: Spanish 3.$c$,
   $c$The Spanish 4 curriculum refines and enhances students' language skills, developing their ability to communicate effectively in oral and written Spanish within a thematic context. Students move toward less structure and more cumulative knowledge and self-initiated responses. They broaden their understanding of cultures from Spanish-speaking communities around the world, relating them to their own experiences. The course focuses on six essential themes: global challenges, beauty and aesthetics, families and communities, personal and public identities, contemporary life, and science and technology. Students explore each theme through written and audio resources, acquire new vocabulary, and practice writing and speaking formally and informally. The course emphasizes the use of language for active communication and is conducted entirely in Spanish. Prerequisites: Spanish 3 or equivalent.$c$),

  ($c$Spanish Communication$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${10,11,12}$c$::int[], false,
   $c$An advanced elective, conducted in Spanish, developing oral communication skills and interaction with native speakers. Prereq: Spanish 4.$c$,
   $c$Advanced Spanish Communication is an advanced elective course, conducted in Spanish, designed to help students develop a dynamic range of advanced oral communication skills and strategies and acquire the literacy skills necessary to be effective communicators with native language speakers. Students develop the communicative skills and oral expressiveness necessary to engage in a variety of real-life situations and apply their skills to issues facing Spanish-speaking communities around the world. Through close readings and analysis of colloquial texts and conversations, as well as individual and group practice, students develop proficiency in Spanish mechanics and learn to conduct research and interpersonal interviews, deliver an original speech, write on demand, and interact with native speakers. Students examine daily interactions in different Spanish-speaking communities and create cross-cultural connections between contemporary language phenomena, including advertising, journalism, sports, and slang. Prerequisites: Spanish 4 or equivalent.$c$),

  ($c$Advanced Topics in Spanish: Cultural Analysis and Lifestyles$c$, $c$Languages$c$, $c$Languages$c$, $c$all-year$c$, $c${10,11,12}$c$::int[], false,
   $c$Explore contemporary issues in the Spanish-speaking world through readings, film, music, and social media. Prereq: Spanish 4.$c$,
   $c$This course explores contemporary issues in the Spanish-speaking world. Through a variety of readings, film viewings, discussions, interviews, music, and social media, we engage more closely with the culture, politics, and social and human landscape of Spanish-speaking communities. Students continue to build vocabulary, idiomatic expressions, and grammatical control with the goal of developing their interpretive, interpersonal, and presentational skills and progressing through ACTFL's Advanced proficiency standards. Students read and analyze texts, give oral and written presentations, and participate in discussions and debates related to the topics of study. A key component is developing relationships with native speakers to gather a variety of perspectives and opinions. Prerequisites: Spanish 4 or equivalent.$c$),

  ($c$Languages Teaching Fellowship$c$, $c$Languages$c$, $c$Languages$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired language course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$),

  -- ============================= MATH =============================
  ($c$Abstract Algebra$c$, $c$Math$c$, $c$Math$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A gateway to advanced mathematics studying groups, fields, and rings, and learning to write mathematical proofs. No specific prerequisites.$c$,
   $c$This course is the canonical gateway to advanced mathematics, comprising the study of structures such as groups, fields, and rings. These abstract structures are generalizations of more familiar number systems, and allow mathematicians to devise new "numbers" and "operations" applicable in a wide array of disciplines. Abstract algebra is an excellent venue for learning to write mathematical proofs, and is indispensable in math, theoretical physics, cryptography, and more. This course requires commitment and effort but has no specific prerequisites. Any student may enroll, regardless of previous mathematical experience, as long as they are prepared to engage earnestly with the challenges presented. We study groups, subgroups, normal subgroups, quotient groups, order of elements, cosets, orbits, and fields. Students who begin with some familiarity may explore parallel notions in ring theory as well as more advanced topics such as the Sylow theorems.$c$),

  ($c$Advanced Probability$c$, $c$Math$c$, $c$Math$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A calculus-based approach to random variables, classical distributions, limit theorems, and Markov chains. Prereq: Calculus.$c$,
   $c$This class takes a calculus-based approach to discrete and continuous random variables, Bernoulli and Poisson processes, probability generating functions, classical distributions (normal, t, binomial, hypergeometric, negative binomial, exponential, Poisson, beta, gamma), moments, joint distributions, multivariate normal distribution, conditional expectation, formalization of the law of large numbers, the central limit theorem, the theoretical basis of statistical tests, Markov chains, and branching processes. We develop an intuitive understanding of the processes underlying the notation, with an emphasis on clever, elegant problem-solving. We use programming and simulation-based investigations to understand distributions, moment calculations, and limit theorems. While largely theoretical, we develop probability theory with an eye toward seeking truth in understanding natural and social phenomena. Prerequisites: Calculus.$c$),

  ($c$Algebra Techniques$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9}$c$::int[], false,
   $c$Builds competency with algebraic fundamentals to support success in Math 1, in which students are dual-enrolled. Coreq: Math 1.$c$,
   $c$This course builds students' competency with the fundamentals of algebraic thinking and technique necessary for success across our mathematics and science programs. Students practice and solidify techniques such as order of operations, simplifying and manipulating algebraic expressions, symbolic manipulation, solving equations and inequalities with linear, absolute value, and quadratic components, and working with exponents and radicals. Along the way, students develop proficiency in recognizing structure, moving between representations in problem spaces, abstracting from repeated computations to the language of algebra, and moving between process and object views of mathematical concepts. Throughout the course, there is an emphasis on connecting this algebraic toolkit to geometric spaces and applied/contextual problems, supporting students in their Math 1 course, in which they are dual-enrolled. Corequisites: Math 1.$c$),

  ($c$Calculus$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A rigorous year-long course in single-variable calculus interweaving classical, analytic thinking with applications. Prereq: Math 3.$c$,
   $c$Calculus is a rigorous year-long course in single-variable calculus. This course interweaves two approaches: the classical and the applied. First, it immerses students in rigorous, analytic thinking through an emphasis on deductive reasoning and careful proofs of deep results. Students are expected to derive formulas from basic principles and to articulate verbally the connections between mathematical ideas. Second, students encounter a wealth of applications in physics, economics, and other sciences, ranging from fluid dynamics to compound interest, discovering the transformative power of calculus as a problem-solving tool. The curriculum covers limits, epsilon-delta proofs, differentiation rules, applications of differentiation, differential equations, integration and various integration techniques, the fundamental theorem of calculus, transcendental functions, power series, convergence of sequences and series, and various applications. Prerequisites: Math 3.$c$),

  ($c$Complex Analysis$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$An introduction to the theory of analytic functions of one complex variable, a very challenging course. Prereq: Calculus (Linear Algebra or Multivariable Calculus ideal).$c$,
   $c$This is an introduction to the theory of analytic functions of one complex variable. Complex analysis is a fascinating field of study from a purely theoretical point of view, as well as a powerful tool for solving a wide array of applied problems. It is related to many mathematical disciplines, including real analysis, differential equations, algebra, and topology. The numerous applications include wave propagation phenomena in electrodynamics, optics, fluid mechanics, and quantum mechanics; diffusion problems such as heat and contaminant diffusion; engineering tasks such as the computation of buoyancy and resistance; and signal processing and communication theory. This is a very challenging course. Prerequisites: Calculus, and ideally one more elective such as Linear Algebra or Multivariable Calculus.$c$),

  ($c$Computational Biology$c$, $c$Math$c$, $c$Math$c$, $c$spring$c$, $c${10,11,12}$c$::int[], false,
   $c$Explore the intersection of biology and mathematics through mathematical models of biological processes. Prereq: Math 3.$c$,
   $c$This course explores the intersection between biology and mathematics. Students are introduced to the use of mathematical models for exploring biological processes. We investigate a diverse set of biological dynamics, including the genetic code, the relationship between structure and function of proteins, the forces that guide evolution in viruses, bacteria, and eukaryotes, population dynamics, competition and cooperation among species, metabolism and catalysis, neural excitation and inhibition, immunological memory, and origins and detection of life. The modeling process plays a central role, offering opportunities to study various mathematical concepts in context, including dynamical systems, Markov chains, random walks, and optimization. The class is structured around modules that students explore in independent groups, culminating in artifacts shared through symposia and curated into a final portfolio. Prerequisites: Math 3.$c$),

  ($c$Core Mathematics Intensive X$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10,11}$c$::int[], false,
   $c$One of two required courses in the accelerated Math 2-3 Integrated Program; taken concurrently with Core Mathematics Intensive Y. Prereq: Math 1 and department approval.$c$,
   $c$Core Mathematics Intensive X is one of two required courses that together comprise the Core Mathematics Intensive: Math 2-3 Integrated Program, a yearlong alternative pathway through Nueva's Core Mathematics program for students seeking a challenging course of study. The program integrates and reorders core content typically addressed across Math 2 and Math 3 into a single, coherent sequence, engaging students deeply with algebraic, geometric, and functional ideas while maintaining a demanding pace and workload. Students enrolled in this course must also enroll concurrently in Core Mathematics Intensive Y. Placement is determined by department approval based on demonstrated readiness for sustained acceleration. This program replaces the former Math 1X/Math 2X Booster program. Prerequisites: Math 1 and Math Department Approval. Corequisites: Core Mathematics Intensive Y.$c$),

  ($c$Core Mathematics Intensive Y$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$The companion course to Core Mathematics Intensive X in the accelerated Math 2-3 Integrated Program. Prereq: Math 1 and department approval.$c$,
   $c$Core Mathematics Intensive Y is the companion course to Core Mathematics Intensive X and is taken concurrently as part of the Core Mathematics Intensive: Math 2-3 Integrated Program, a yearlong alternative pathway through Nueva's Core Mathematics program. The program integrates and reorders core content typically addressed across Math 2 and Math 3 into a single, coherent sequence that emphasizes mathematical reasoning, problem solving, modeling, and clear communication of ideas. Enrollment in this course requires concurrent enrollment in Core Mathematics Intensive X. Placement is determined by department approval based on demonstrated readiness for sustained acceleration. Prerequisites: Math 1 and Math Department Approval. Corequisites: Core Mathematics Intensive X.$c$),

  ($c$Differential Equations$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Search for functions satisfying growth properties, combining analytic and computational methods. Prereq: Calculus.$c$,
   $c$This elective introduces students to the search for functions that satisfy a variety of growth properties. Unlike the more familiar algebraic equations, where the unknowns are numbers, here the unknowns are the functions themselves. We explore constructive solution techniques, like the integrating factor, characteristic equations, the Laplace transform, and Fourier series. We proceed to investigate systems of differential equations and their asymptotic properties, in applications ranging from physics, biology, and economics. In this course we combine analytic methods with computational ones, which allow us to simulate, approximate, and visualize complex dynamics. The course culminates with a term project based on the description and analysis of a modeling challenge. Prerequisites: Calculus.$c$),

  ($c$Geometries Beyond Euclid$c$, $c$Math$c$, $c$Math$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Explore diverse forms of geometry through hands-on, student-driven investigations and monthly symposia. Prereq: Math 3.$c$,
   $c$This course exposes students to the diverse forms that the classical study of Geometry has taken over the last two hundred years, through a series of hands-on, student-driven investigations. After a shared introductory unit, students choose three month-long modules to explore independently in small groups. Each module includes readings, both expository and technical, computational and applied challenges, problem solving and writing, and inspiring research prompts. Along the way, students produce artifacts, which they exhibit at monthly Geometry Symposia, culminating in portfolios that they curate under the teacher's mentorship. Modules explore topics ranging across algebraic, combinatorial, differential, hyperbolic, projective, and tropical geometries. Math 3 is a required prerequisite and Calculus is recommended preparation. Prerequisites: Math 3.$c$),

  ($c$Linear Algebra$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Study the properties of matrices with a markedly abstract approach, building communication and analysis skills. Prereq: Math 3.$c$,
   $c$Linear algebra is the branch of mathematics concerning the properties of matrices. It has wide-ranging applications in abstract algebra, functional analysis, and many natural and social sciences, and is particularly malleable to the student's interests, whether theoretical, applied, or computational. Our approach this year is markedly abstract, giving students the opportunity to acquire communication and analysis skills that benefit them in further math classes. These concepts include vectors and vector spaces, linear transformations and matrix representations, determinants, linear dependence and independence, subspaces, bases, and dimensions, orthogonal bases and projections, Gram-Schmidt orthogonalization, Cramer's Rule, linear models and least-squares problems, eigenvectors and eigenvalues, and singular value decomposition. Prerequisites: Math 3.$c$),

  ($c$Math 1$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10}$c$::int[], false,
   $c$Builds competency in mathematical reasoning, integrating geometry and algebra and building the language and foundations of mathematics.$c$,
   $c$This course builds students' competency in mathematical reasoning, focusing on generalizing patterns, building strong arguments, and finding multiple approaches to solving problems. Students learn to ask probing questions, reflect on their problem-solving process, and clearly communicate their findings. Students develop mathematical fluency by integrating geometry and algebra through rich introductions to geometric construction, formal proofs and notation, similarity and congruence, right triangle trigonometry, coordinate geometry, and unit circle trigonometry. Students also revisit and expand on their knowledge of forms of linear, quadratic, absolute value, and piecewise functions, with an introduction to function transformations and the library of essential parent functions and analysis of key features. The underlying focus for the year is on building the language and foundations of mathematics.$c$),

  ($c$Math 2$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10,11}$c$::int[], false,
   $c$Builds on Math 1 with further geometry and introductions to exponential/logarithmic functions, polynomials, and modeling. Prereq: Math 1.$c$,
   $c$Math 2 builds on the content and skills developed in Math 1, including further studies in geometry (polygon angles and areas, 3D geometry, circle theorems, general triangle trigonometry, and unit circle trigonometry review) and introductions to exponential and logarithmic functions, higher degree polynomials and factoring, complex numbers, and mathematical modeling. Throughout the course, students work individually and in groups to derive, make sense of, and apply what they are learning to solve compelling problems, while continuing to develop their ability to reflect on and communicate their thinking effectively. Prerequisites: Math 1.$c$),

  ($c$Math 3$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Spirals deeper into Math 1 and 2 content and prepares students for advanced studies in calculus, statistics, and beyond. Prereq: Math 2.$c$,
   $c$Students spiral deeper into the content developed in Math 1 and Math 2 and prepare for advanced studies in calculus, statistics, number theory, abstract algebra, and other math electives, as well as physics, game theory, economics, and other science/social science electives, through thought-provoking problems and projects. As topics from previous courses are deepened, Math 3 content includes function families and their graphs, trigonometric proofs and identities, complex numbers, parametric equations, polar coordinates, and various topics in geometry, including vectors, circles, and conics, as well as an introduction to topics in calculus. Math 3 serves as a culminating course for Nueva's integrated Math curriculum, helping students see mathematics as a cohesive and beautiful system. Prerequisites: Math 2.$c$),

  ($c$Math and Philosophy for Human Flourishing$c$, $c$Math$c$, $c$Math$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Explore the interface between philosophy, mathematics, and literature in search of mathematical truth and meaning. Prereq: Math 1.$c$,
   $c$This elective explores the fertile interface between philosophy, mathematics, and literature, in search of the role it plays in the human condition. Our main quarry is mathematical truth and its ontology. From the economy to ecology, our bodies to the body politic, complexity is the common denominator that, paradoxically, explains what remains stubbornly just outside our comfort zone. What is the meaning of proof, or truth, in the era of polymath blogs and computer-assisted experimental mathematics? This is primarily a reading and writing course, with mathematics serving as the context. We read the musings of mathematicians as they ponder the source of meaning and purpose in their work, investigating core philosophical questions at the foundation of mathematics, from ontology and metaphysics to epistemology, ethics, and aesthetics. These investigations are always inspired by concrete mathematical explorations designed to be accessible to students with diverse mathematical backgrounds. Prerequisites: Math 1.$c$),

  ($c$Mathematical Modeling$c$, $c$Math$c$, $c$Math$c$, $c$fall$c$, $c${10,11,12}$c$::int[], false,
   $c$Develop creative mathematical approaches to model real situations from biology, economics, engineering, and more. Prereq: Calculus.$c$,
   $c$Students are presented with situations from biology, economics, engineering, logistics, management science, politics, and daily life. They develop creative mathematical approaches to build, test, and refine models, focusing on applying the formal mathematics they already know. Modeling problems draw on concepts from logistics and operations research, measurement and regression, game theory and decision theory, algorithmic design, and geometric design and inference. This class is heavily project-based, and students work in teams to produce models and formal write-ups of their approaches and results. Prerequisites: Calculus.$c$),

  ($c$Multivariable Calculus$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Extend single-variable calculus to functions of several variables, working in two, three, and more dimensions. Prereq: Calculus.$c$,
   $c$Our study of multivariable calculus builds upon techniques learned in single-variable calculus, extending the realm of applications to problems in two, three, and more dimensions. The course provides a venue for students to combine and extend many mathematical techniques from previous courses and apply them to problems of greater complexity. Students generalize their knowledge of differentiation and integration to functions of several variables, learning to work with and visualize two- and three-dimensional functions, vectors, and vector fields. We study techniques for working in n dimensions, including parametric equations, polar coordinates, vectors and vector operations, directional derivatives and gradients, multiple integration, line and surface integrals, Taylor's expansion in n dimensions, and Green's, Stokes', and Gauss' Theorems. Whenever possible, students work with physical or computer models to aid visualization and solve real-world problems, while honing formal mathematics skills through proofs and presentations. Prerequisites: Calculus.$c$),

  ($c$Number Theory$c$, $c$Math$c$, $c$Math$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A semester study of the integers and discrete systems, with applications in cryptography and computer science.$c$,
   $c$Number theory is a branch of theoretical mathematics with both a wealth of recreational problems and applications in cryptography and computer science. For example, Fermat's Last Theorem and RSA encryption both have their roots in number theory. In our semester-long study of numbers, we begin by considering properties of the integers, mainly various aspects of divisibility. We also investigate other discrete systems such as modular arithmetic and rational numbers. Advanced students may have opportunities to study topics such as the Gaussian integers, quadratic residues, and Diophantine equations.$c$),

  ($c$Statistics$c$, $c$Math$c$, $c$Math$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Learn to interpret data and make statistically significant arguments, exploring study design and inference. Prereq: Math 2.$c$,
   $c$How do we become critical consumers of data? How do we use data effectively to create an argument that is statistically significant? What must we be cautious of when designing an experiment? This course in statistics first explores how to interpret categorical and quantitative data, including both 1- and 2-variate, and then explores different tests that allow us to make inferences and justify conclusions. In the second semester, we explore study design deeply and technically for a degree of association and inference. We also look at sampling techniques as they relate to inference about populations. In addition, we delve into the power of studies before embarking on independent study of inferential statistics within the context of epidemiological and environmental factors. Prerequisites: Math 2.$c$),

  ($c$Math Teaching Fellowship$c$, $c$Math$c$, $c$Math$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired math course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$),

  -- ============================= SCIENCE =============================
  ($c$Advanced Mechanics$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${10,11,12}$c$::int[], false,
   $c$An in-depth, calculus-based study of mechanics and elements of mechanical engineering. Prereq: Physics and Calculus.$c$,
   $c$This course represents an in-depth study of mechanics, including the mathematical tools of calculus and elements of mechanical engineering. Unlike the treatment in first-year physics, where objects are usually approximated as point masses or as having infinite stiffness, here we consider an object's center of mass, rotational inertia, modulus of elasticity, or other properties. Students solve problems of substantially greater complexity than those in earlier classes. We also aim for students to develop a robust set of scientific practices. Students explore physics experimentally whenever practical; when a phenomenon is not tractable to classroom demonstration, digital simulations are employed. Topics include kinematics, dynamics, center of mass, impulse and momentum, conservation and transformations of energy, gravity, rotation and rolling, and oscillations and waves. Prerequisites: Physics and Calculus.$c$),

  ($c$Anatomy and Physiology$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${11,12}$c$::int[], false,
   $c$A yearlong exploration of the human body's structure and function, with dissections, histology, and imaging. Prereq: Biology.$c$,
   $c$Anatomy and Physiology is a yearlong exploration of the human body's structure and function, designed for students interested in medicine, exercise science, or simply understanding how their body works. In the fall semester, we investigate how the body's organization supports life's essential functions, beginning with cell theory, structure-function relationships, and levels of organization. Students engage in hands-on experiences such as dissections, histology slide analyses, medical imaging studies, and interactive labs. In the spring semester, students cross-apply fall concepts with new concepts that govern how physiological systems work together in a whole organism, such as homeostasis and interdependence. By applying their knowledge to novel scenarios—including unfamiliar organ systems and even other species—students build adaptability, problem-solving skills, and confidence. Across both semesters, the skill focus is on developing critical thinking and research-backed study techniques tailored to each student. Prerequisites: Biology.$c$),

  ($c$Biology$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${10}$c$::int[], false,
   $c$A full-year 10th-grade course developing understanding of the living world through authentic scientific research. Prereq: Chemistry.$c$,
   $c$Our goal in Biology is to develop students' understanding of and appreciation for the living world in all its complexity. We approach the study of life through several key lenses, including form and function relationships and variations in size and scale. Throughout the year, students perform authentic scientific research and participate in scientific discourse just as any scientist would, developing an understanding of the process of science through direct experience. Students learn to engage with peer-reviewed scientific articles, design sound experiments through iteration, collect and present data, and communicate scientific information to various audiences. Essential questions include: What is life, what capacities does it entail, and what does it require? How do principles from chemistry dictate how biological molecules function? Why is life tied to the need for a heritable and changeable instructional code? How has evolution shaped life on earth? How are the characteristics of an organism shaped by its genetic code and environment? And how do populations and their environments interact, and how is human activity reshaping ecological relationships? Prerequisites: Chemistry.$c$),

  ($c$Biology Research Teams 1$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${10,11}$c$::int[], false,
   $c$A yearlong, hands-on introduction to biology research using model organisms; application required. Prereq: Chemistry and completed course application.$c$,
   $c$There is an application process to be considered for enrollment in Biology Research Teams 1 (BRT 1). In this class, we learn deeply about the scientific process by exploring its history and methods and directly participating in experimental biological research. We learn about the history of the scientific process, current philosophical issues surrounding science, how to approach experimental design and data analysis to mitigate bias and make sound claims, and how to engage with and learn from the scientific literature. Students spend significant periods performing experiments to investigate biological questions using model organisms like bacteria, fruit flies, and roundworms, learning modern laboratory techniques and tools, collecting and analyzing data, and sharing findings in written, visual, and oral formats. This yearlong course prepares students for future research endeavors and is a required course for the student-led advanced course, Biology Research Teams 2. A selection committee assesses potential enrollees based on interest, motivation, and demonstrated skills. Prerequisites: Chemistry and Completed Course Application.$c$),

  ($c$Biology Research Teams 2$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${11,12}$c$::int[], true,
   $c$A student-led advanced research course where teams propose and pursue novel, long-term biology research projects. Prereq: Biology Research Teams 1.$c$,
   $c$In Biology Research Teams 2, students propose novel, long-term research projects to experimentally address significant scientific questions, and they pursue a subset of these projects in small, student-led groups over the course of 1 to 2 years. These research projects in molecular, cellular, and behavioral biology are significant (often presented at a scientific conference); they are created, pushed forward, and led by students; they are iterative; and they allow student leaders to train their peers in a structured process guided by the teachers. The reading of scientific literature, theoretical understanding of the scientific process, and hands-on experimental training from Biology Research Teams 1 allow teams to collaboratively drive a multi-faceted research project forward. All students practice project management and reverse design skills, while team leads develop their ability to coordinate, mentor, and inspire their team. Students learn to write about, display, and present their data through lab meetings, scientific posters, and written abstracts. Prerequisites: Biology Research Teams 1.$c$),

  ($c$Bioorganic Chemistry$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${10,11,12}$c$::int[], false,
   $c$Discover organic chemistry experimentally, from lab techniques to the chemistry of proteins and enzymes. Prereq: Chemistry. Coreq: Math 3.$c$,
   $c$The objective of this course is to discover organic chemistry, the chemistry of carbon, experimentally. Organic molecules such as petrochemicals, natural products, biomolecules, and pharmaceuticals are an integral part of our daily lives. Selected experiments present common laboratory practices and techniques, such as chromatography and distillation, and illustrate the chemistry of a wide range of functional groups. Other experiments allow students to synthesize specific compounds or explore reactions fundamental to organic synthesis: nucleophilic substitution, nucleophilic addition, electrophilic addition, esterification, and oxidation. Additional experiments emphasize discovery-based approaches, letting students develop their own protocols as they might in a research laboratory. Topics include chemical bonding and molecular structure, hydrocarbons, kinetics and energy of a reaction, stereochemistry, functional groups, reaction mechanisms, chemistry of proteins and enzymes, and an independent project. Prerequisites: Chemistry. Corequisites: Math 3.$c$),

  ($c$Chemical Engineering$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${10,11,12}$c$::int[], false,
   $c$Apply chemistry, physics, biology, and engineering to real-life problems through mini research projects. Prereq: Chemistry. Coreq: Math 3.$c$,
   $c$Chemical engineers are multi-disciplinarians who apply principles of chemistry, physics, biology, and engineering to solve a range of practical real-life problems, from large-scale production of pharmaceuticals to the development of novel renewable energies or the design of new biomaterials. In this course, some aspects of chemical engineering, such as applications to renewable energies, are investigated with mini research projects including many elements of design thinking such as experimentation on a small scale, process analysis, iteration, and redesign. The general goals are to foster reasoning and analytical skills, mostly in the context of physical and analytical chemistry, through hands-on activities. Students gather qualitative or quantitative data from experimental situations, understand and accurately represent data, and use data to evaluate predictions, support structure determination, and propose plans of action. Projects are supported by mini-lectures to provide a base of content. Prerequisites: Chemistry. Corequisites: Math 3.$c$),

  ($c$Chemistry$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${9}$c$::int[], false,
   $c$Nueva's ninth-grade science: a unified introduction to the principles of chemistry, applied in hands-on ways.$c$,
   $c$Nueva's ninth-grade science provides a unified introduction to the principles that describe the natural world at its most fundamental level. The course aims to improve students' understanding of the world around us and to make their thinking more rigorous by introducing principles of chemistry and applying those concepts in hands-on ways to real-world examples. We also aim for students to develop a robust set of scientific practices: methods for asking questions, designing and carrying out experiments, interpreting the results, and communicating their conclusions to others. Topics studied this year include gas properties, the atomic nature of matter, bonding in materials, chemical reactions, stoichiometry, and acids and bases.$c$),

  ($c$Chemistry Consulting$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${10,11,12}$c$::int[], false,
   $c$A laboratory-based class where students act as real-world consultants across physical, inorganic, and analytical chemistry. Prereq: Chemistry and Math 2.$c$,
   $c$Chemistry Consulting is a laboratory-based class that exposes students to a wide range of chemistry and engineering disciplines through a collaborative, project-aligned curriculum featuring open-ended design, mystery, or analysis questions. The course focuses on four chemistry disciplines: physical, inorganic, analytical, and physical organic chemistry. Students pose as real-world consultants and work in groups or as a class to master the course content and habits of mind while addressing real-world problems related to polymer, solar, plastic, battery, spectroscopic, and medicinal chemistry. The year is divided approximately 85% for new chemistry topics (learning, laboratories, designing/building, homework) and 15% for consulting activities (company events, presenting work, field trips, meeting with clients). The course provides an opportunity to experience the workings of a human-centered profession, including visits to a local consulting firm. Prerequisites: Chemistry and Math 2.$c$),

  ($c$Drug Design$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${11,12}$c$::int[], false,
   $c$A lab-based introductory medicinal chemistry class exploring the design of new therapeutics. Prereq: Chemical Engineering or Bioorganic Chemistry.$c$,
   $c$This lab-based introductory medicinal chemistry class emphasizes the application of biological, chemical, and pharmacological concepts in the investigation of drug discovery. Medicinal chemistry deals with the discovery and design of new therapeutic chemicals and their development into useful medicines. The aim of the class is to introduce students to the basic principles of medicinal chemistry and how they are applied to the design of new therapeutics. The emphasis is that therapeutically relevant small molecules are chemical entities whose biological properties depend on chemical structure and physicochemical properties, so modifications of these properties influence biological behavior. By the end of the course, students have a greater awareness of "drug-like" properties (lipophilicity, H-bonding potential, toxicity potential) and approaches to modify pharmacological properties. Topics include spectroscopy, intro to anatomy and physiology, structure-activity relationships of antibacterials, and the relationship between structure and ADME. Prerequisites: Chemical Engineering or Bioorganic Chemistry.$c$),

  ($c$Environmental Earth Science$c$, $c$Science$c$, $c$Science$c$, $c$fall$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Examine how energy and elements shaped Earth and civilization, using the planetary boundaries framework.$c$,
   $c$Environmental Earth Science (EES) examines how energy and elements have shaped the emergence and evolution of Earth, life, and human civilization. Using an interdisciplinary, systems-level lens, the course develops students' understanding of the biological, chemical, and physical processes that drive the Earth system, with a particular focus on energy flows and biogeochemical cycles. With this foundation, students use the planetary boundaries framework to explore how human activities have pushed Earth's systems out of balance—and evaluate how the clean energy transition, regenerative economics, and sustainable food systems can help restore our planet's health and resilience. Coursework includes readings, short activities, quizzes, and individual and group projects. Students also work in the skywalk garden—planting, sampling, and collecting data in and out of class—and participate in at least one field trip.$c$),

  ($c$Immunology$c$, $c$Science$c$, $c$Science$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$Investigate the immune system through a case-study approach, with a heavy focus on primary literature and modeling. Prereq: Biology.$c$,
   $c$Every day, the cells of your immune system target and destroy pathogens. The immune system is highly specialized to resist constant assault, but the tools at its disposal often cause harm to the body itself. Our course investigates the underlying function of the immune system through a case-study approach, analyzing real-life examples of how the immune system can both fight and cause disease. After a whirlwind review of cell biology, students gain a bird's-eye view of the immune system by focusing on how the components of the innate and adaptive immune system interact. We model the stages of innate immune response and investigate how dysregulation can cause Crohn's disease, perform skits to model T-cell activation, and examine the medical records of a bone marrow transplant patient to determine the role of hematopoiesis in robust immune response. With a heavy focus on primary literature and modeling, this class is an opportunity to ask and answer questions about how our own bodies function. Prerequisites: Biology.$c$),

  ($c$Marine Environments$c$, $c$Science$c$, $c$Science$c$, $c$spring$c$, $c${9,10,11,12}$c$::int[], false,
   $c$A rigorous examination of the interactions between marine and human systems, spanning ecology, chemistry, and geology.$c$,
   $c$Marine Environments is a rigorous examination of the interactions between marine and human systems. The course develops students' understanding of the many disciplines that underlie marine science—ecology, biology, chemistry, geology—and how the ocean interacts with the climate and human society. Some of the topics explored include ocean acidification/warming, biogeochemical cycles, and marine ecology. Students engage in several hands-on activities, and they spend several weeks growing and maintaining algal cultures under different conditions. The overarching goal is for students to develop the scientific literacy and skills necessary to support ocean health and address problems of human impact.$c$),

  ($c$Mechanisms of Cancer$c$, $c$Science$c$, $c$Science$c$, $c$fall$c$, $c${11,12}$c$::int[], false,
   $c$Understand the pathways that control cell growth and how they are hijacked in cancer, alongside societal lenses. Prereq: Biology.$c$,
   $c$Together, the many thousands of genes in the human genome create a self-assembling system, a human being. All of the cells in this system use those genes in different ways, becoming constrained in where they exist, how long they exist, what they consume, and what they produce. The human genome, however, has vulnerabilities. Mutations can cause cells to redefine their previous location, lifespan, and activities; a cell like this can grow and divide without typical boundaries, creating cancer. In this class, we work to understand the pathways that control cell growth and division under normal circumstances and that are hijacked when certain cancerous mutations occur. We also explore the molecular basis for many cancer treatments. Although we spend much of our time taking a scientific approach to cancer, we also examine it through other lenses, such as personal narratives, the history of cancer, healthcare economics, and health disparities. Through creative and analytical projects, students develop paper-reading and communication skills, deepen their understanding of molecular and cellular biology, and analyze complex societal problems. Prerequisites: Biology.$c$),

  ($c$Modern Physics$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${10,11,12}$c$::int[], false,
   $c$Builds on first-year physics, covering developments from the late 19th century to today. Prereq: Physics.$c$,
   $c$This course builds on the first-year introduction to physics and generally covers developments from the late 19th century through the present day. Transitioning from the relatively intuitive principles of classical physics, students explore the more conceptually profound and challenging ideas demanded by 20th- and 21st-century science. Students study phenomena experimentally whenever practical; when a phenomenon is not tractable to classroom demonstration, digital simulations are employed. Students explore new content primarily through teacher-created screencasts and readings, with some Socratic lecture and classroom discussion, and spend most of their classroom time learning to solve problems, design and perform experiments, and analyze demonstrations of (sometimes unexpected) results. Topics include electromagnetism, relativity, nuclear physics, quantum physics, and the standard model of particle physics. Prerequisites: Physics.$c$),

  ($c$Optics & Astrophysics$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${10,11,12}$c$::int[], false,
   $c$Explore the physics of stars with a focus on optical tools such as cameras, telescopes, and spectroscopes. Prereq: Physics.$c$,
   $c$In this year-long class, students explore the physics of stars with a particular focus on optical tools such as cameras, ground- and space-based telescopes, and spectroscopes—all with a modern, digital twist. Physics topics include the nature of light (refraction, reflection, dispersion, polarization, interference, and diffraction); the formation, life, and death of stars (including nuclear fusion and relics such as white dwarfs, neutron stars, and black holes); the formation and observation of planetary systems (including extrasolar systems); Big Bang cosmology; dark matter and dark energy; inflation; and frontier topics that vary according to the discoveries of the day. Students take data directly with digital cameras and also make use of publicly available data for deeper study. Prerequisites: Physics.$c$),

  ($c$Physics$c$, $c$Science$c$, $c$Science$c$, $c$all-year$c$, $c${9,10,11,12}$c$::int[], false,
   $c$Introduces principles of physical sciences applied to real-world examples, emphasizing Newton's laws. Coreq: Math 2 (or higher).$c$,
   $c$This course aims to improve students' understanding of the world around us, and make their thinking more rigorous, by introducing principles of physical sciences and applying those concepts to real-world examples. We also aim for students to develop a robust set of scientific practices: methods for asking questions, designing and carrying out experiments, interpreting the results, and communicating their results to others. The course emphasizes important principles such as Newton's laws and includes more specific phenomena as necessary to illuminate those principles. Students explore physics experimentally whenever practical; when a phenomenon is not tractable to classroom demonstration, digital simulations are employed. Topics include kinematics, projectile motion, dynamics, Newton's laws, forces, circular motion, energy and its conservation, momentum and its conservation, rotational motion, universal gravitation and Kepler's laws, simple harmonic motion and waves, sound, light and optics, refraction/diffraction/interference, and thermodynamics. Corequisites: Math 2 (or higher).$c$),

  ($c$Physics Research$c$, $c$Science$c$, $c$Science$c$, $c$fall$c$, $c${10,11,12}$c$::int[], true,
   $c$A fall research course exploring topics for the U.S. Invitational Young Physicists Tournament; application required. Prereq: Physics and consent of instructor.$c$,
   $c$There is an application process to be considered for enrollment in Physics Research. This fall-semester course provides an opportunity for students to delve deeply into physics research by exploring topics curated for the U.S. Invitational Young Physicists Tournament. These topics are chosen to be challenging but accessible at the advanced high school level, and usually require a combination of theoretical, numerical/modeling, and experimental investigation. Topics may include phenomena in optics, classical mechanics, fluids, gravitation, and electricity and magnetism. Examples of past tasks include writing code to simulate the trajectory of an object subject to aerodynamic and gravitational forces, building an apparatus to generate and photograph rainbows, or exploring the behavior of pristine and damaged tuning forks. Extensive quantitative data collection and analysis is emphasized. A committee of physics teachers assesses potential enrollees based on interest, motivation, and demonstrated research and problem-solving skills. Prerequisites: Physics and Consent of Instructor.$c$),

  ($c$Semiconductor Processes$c$, $c$Science$c$, $c$Science$c$, $c$spring$c$, $c${10,11,12}$c$::int[], false,
   $c$Explore the processes, metrology, and equipment used to manufacture integrated semiconductors. Prereq: Modern Physics (Fall Semester).$c$,
   $c$How do they make the chips that make your computer work? Students explore the processes, metrology, terminology, concepts, and equipment commonly used in the manufacture of integrated semiconductors. Students explore more deeply into individual process or metrology steps and have the chance to delve into integrated circuit design or special topics of their own choosing. Labs include photolithography and profilometry. Taking advantage of our proximity to Silicon Valley, we include guest speakers from the semiconductor industry and a field trip to a manufacturing facility. Concepts include how to control processes that cannot be seen and the optimization of yield. Prerequisites: Modern Physics (Fall Semester).$c$),

  ($c$Sensory Neuroscience$c$, $c$Science$c$, $c$Science$c$, $c$spring$c$, $c${11,12}$c$::int[], false,
   $c$Explore sensory systems down to the molecular level and fundamental concepts in neuroscience. Prereq: Biology.$c$,
   $c$How do we perceive the world around us? Somehow, our brains interpret physical phenomena like light, sound waves, molecules, and temperature to produce our sense of what is happening around us and in our bodies. In this class, we explore sensory systems down to the molecular level, understanding how physical stimuli are translated into a language that our brains can read and generate meaning from. Through this exploration, students learn fundamental concepts in neuroscience, such as how neurons communicate. The unique experiences of people with sensory issues help us consider the holistic nature of our perceptions, while the sensory "superpowers" of other organisms (such as infrared sight and magnetic sense) illuminate how evolution has shaped our sense of the world. Students learn through various sources and modalities, including extracting information from scientific research articles and translating it for specific audiences, and apply their knowledge in a culminating project with options for experimental design, technology design, or science fiction story-writing. Prerequisites: Biology.$c$),

  ($c$Science Teaching Fellowship$c$, $c$Science$c$, $c$Science$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired science course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$),

  -- ============================= SOCIAL EMOTIONAL LEARNING (SEL) =============================
  ($c$Social Emotional Learning 9$c$, $c$SEL$c$, $c$SEL$c$, $c$all-year$c$, $c${9}$c$::int[], false,
   $c$A 9th-grade social-emotional on-ramp to the Upper School, meeting once per week alternating with DCI 9.$c$,
   $c$The Social-Emotional Learning (SEL) class is a part of Nueva's SEL program, running from preK-12. The SEL program is intended to develop students' capacity for self-reflection, self-regulation, empathy, critical decision-making, and positive social acuity through a skill-based curriculum. Skills we seek to develop include emotional regulation, self-management and awareness, communication, conflict resolution, and goal-setting. In the 9th grade, SEL is intended to be a social-emotional on-ramp to the Upper School experience. We ask students to start building their identity as an Upper Schooler from day one, reflecting on the narratives they have about themselves, and we work on building the ethos of their grade. We tackle common 9th-grade woes: imposter syndrome, perfectionism, and anxieties around success, with a focus on ethical dilemmas and communication skills. By the end of 9th grade, we hope students have a strong sense of themselves, their class ethos, their moral compass, their ability to communicate well, and their next steps. Note: SEL 9 classes meet only once per week, alternating with DCI 9 in the same block.$c$),

  ($c$Social Emotional Learning 10$c$, $c$SEL$c$, $c$SEL$c$, $c$all-year$c$, $c${10}$c$::int[], false,
   $c$A core course focusing on emotional regulation, distress tolerance, relationship skills, and civil discourse. Prereq: SEL 9.$c$,
   $c$Social-Emotional Learning is a core Upper School course that continues the focus on social-emotional learning, an integral part of teaching and learning at Nueva throughout all grade levels. Drawing on content from a variety of disciplines (psychology, philosophy, cognitive science, therapeutic practices, social science), the course combines intellectual discussion and new concepts with self-reflection and practice in how to use this knowledge to develop skills that serve you. In 10th grade, SEL focuses on emotional regulation, distress tolerance, relationship skills, and civil discourse, building on the 9th-grade work in ethics, communication, and identity development. Students deeply practice how to navigate emotional situations, reframe their emotional narratives, and habituate good practices around distress tolerance. In the second semester, we add relationship skills and mind-body knowledge, then combine these threads to practice civil discourse and the art of having hard conversations. Note: SEL 10 classes meet only once per week, providing students one additional free block each week. Prerequisites: Social Emotional Learning 9.$c$),

  ($c$Social Emotional Learning 11$c$, $c$SEL$c$, $c$SEL$c$, $c$all-year$c$, $c${11}$c$::int[], false,
   $c$A core course focused on decision-making and the variables that influence it. Prereq: SEL 10.$c$,
   $c$Social-Emotional Learning is a core Upper School course that continues the focus on social-emotional learning, an integral part of teaching and learning at Nueva throughout all grade levels. Drawing on content from a variety of disciplines (psychology, philosophy, cognitive science, therapeutic practices, social science), the course combines intellectual discussion and new concepts with self-reflection and practice in how to use this knowledge to develop skills that serve you. The focus of SEL in grade 11 is for students to engage more critically in the process of decision-making, and to be aware of the multiple variables that affect their decision-making. Diving into interdisciplinary considerations of what influences us—our emotions, reason, perception, language, and context—students start building an understanding of their own decision-making models, asking how it serves them and how to tailor it to particular scenarios. Note: SEL 11 classes meet only once per week, providing students one additional free block each week. Prerequisites: Social Emotional Learning 10.$c$),

  ($c$Senior Block$c$, $c$SEL$c$, $c$SEL$c$, $c$fall$c$, $c${12}$c$::int[], false,
   $c$A free period assigned to all 12th-grade students in the fall to account for senior-year priorities.$c$,
   $c$Note: All 12th grade students are assigned a free period (i.e. "Senior Block") in their schedule to account for the myriad priorities present in the fall semester of senior year.$c$),

  ($c$Social Emotional Learning 12: The Good Life$c$, $c$SEL$c$, $c$SEL$c$, $c$spring$c$, $c${12}$c$::int[], false,
   $c$The final semester of SEL, framed around the question "What is the Good Life?" Prereq: SEL 11.$c$,
   $c$Social-Emotional Learning is a core Upper School course that continues the focus on social-emotional learning, an integral part of teaching and learning at Nueva throughout all grade levels. Drawing on content from a variety of disciplines (psychology, philosophy, cognitive science, therapeutic practices, social science), the course combines intellectual discussion and new concepts with self-reflection and practice in how to use this knowledge to develop skills that serve you. The final semester of SEL focuses on the good life. As their time at Nueva draws to a close, students have a chance to think about what they want to draw from their time and what they need moving forward into their futures. The theme of asking themselves "What is the Good Life?" frames both of these aspects. This semester of SEL is highly responsive to student concerns and ideas, nimbly following student questions about how to take SEL learning into their next endeavors. Note: SEL 12 classes meet only once per week, providing students one additional free block each week. Prerequisites: Social Emotional Learning 11.$c$),

  ($c$SEL Teaching Fellowship$c$, $c$SEL$c$, $c$SEL$c$, $c$both$c$, $c${11,12}$c$::int[], false,
   $c$A teaching fellowship for students who have successfully completed the desired SEL course. Application per the Teaching Fellow Program Overview.$c$,
   $c$Teaching Fellowships give experienced students the opportunity to support the teaching of a course they have successfully completed. Students will not indicate interest in a Teaching Fellowship using the Course Preference Form. Instead, interested students should complete the Course Preference Form with all elective preferences by the deadline, then follow the guidance and action steps outlined in the Teaching Fellow Program Overview. Prerequisites: 1) Successful completion of the desired course; 2) Read the Teaching Fellow Program Overview for program details, expectations, and timeline.$c$)

) AS x(title, subject, dept, season, grade, retakeable, short_description, long_description)
CROSS JOIN schools s
JOIN departments d ON d.school_id = s.id AND d.name = x.dept
JOIN terms t ON t.school_id = s.id AND t.season = x.season
WHERE s.name = $c$The Nueva School$c$;

